case_project_lane_routing_aliases_and_prefixes_of_every_verb_keep_their_route() {
  skip_lockdiff_case "$FUNCNAME" || return
  local verb
  # the lane's own verbs, spelled every way npm accepts
  for verb in i in ins inst insta instal add isntall install; do
    lane_prepare "lane-route-alias-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run "npm ${verb} clean@2.0.0"
    assert_status 0 "$FUNCNAME: ${verb}" || return
    grep -q $'^PROJECTION\tnpm' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb} did not take the lane"; return; }
  done
  for verb in up upgrade udpate update updat; do
    lane_prepare "lane-route-alias-${verb}" kept@1.0.0 vuln@1.0.0
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 vuln@1.0.1)" lane_run "npm ${verb}"
    assert_status 0 "$FUNCNAME: ${verb}" || return
    grep -q $'^PROJECTION\tnpm' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb} did not take the lane"; return; }
  done
  # ci, spelled every way: the lane's ci (no projection, npm's own frozen check, one frozen installation)
  for verb in ic clean-install install-clean isntall-clean ci; do
    lane_prepare "lane-route-alias-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "npm ${verb}"
    assert_status 0 "$FUNCNAME: ${verb}" || return
    grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb} did not take the lane's ci"; return; }
    assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME: ${verb}" || return
  done
  # dedupe and prune, spelled every way: the lane's projection of that verb
  for verb in ddp dedupe prune; do
    lane_prepare "lane-route-alias-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run "npm ${verb}"
    assert_status 0 "$FUNCNAME: ${verb}" || return
    grep -q $'^PROJECTION\tnpm' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb} did not take the lane"; return; }
  done
  # everything else is untouched: no lane line, today's delegation
  for verb in uninstall un rm remove ls view; do
    lane_prepare "lane-route-alias-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "npm ${verb} kept"
    assert_err_not_contains_fragment 'project lane' "$FUNCNAME: ${verb}" || return
    assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME: ${verb}" || return
  done
  pass "$FUNCNAME"
}

case_project_lane_routing_mise_exec_with_an_inner_command_that_is_not_the_lanes_is_unchanged() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-mise-exec-other" kept@1.0.0
  local script
  # byte for byte: the output with the switch on is the output with it off
  for script in 'mise exec -- npm view kept' 'mise exec -- npm install -g okpkg' 'mise exec -- pnpm add okpkg' 'mise exec -- node script.js' 'mise exec -- npm uninstall kept' 'mise exec -- npm install-test'; do
    : > "${LOG_FILE}"
    lane_run "${script}"
    local status_on="${STATUS}" err_on real_on
    err_on="$(cat "${ERR_FILE}")"
    real_on="$(lane_delegation_of_log)"
    printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
    : > "${LOG_FILE}"
    lane_run "${script}"
    [[ "${STATUS}" == "${status_on}" && "$(cat "${ERR_FILE}")" == "${err_on}" && "$(lane_delegation_of_log)" == "${real_on}" ]] \
      || { printf 'on: %s\n%s\noff: %s\n%s\n' "${status_on}" "${err_on}" "${STATUS}" "$(cat "${ERR_FILE}")" >&2; fail "$FUNCNAME: ${script} differs with the switch on"; return; }
    printf '{"install":{"project_lane":true}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
  done
  # a global install under mise: the lane hands it on, and the outer mise runs the original command, as today
  : > "${LOG_FILE}"
  lane_run 'mise exec -- npm install -g okpkg'
  assert_log_contains $'REAL\tmise\texec\t--\tnpm\tinstall\t-g\tokpkg' "$FUNCNAME" || return
  assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME" || return
  pass "$FUNCNAME"
}


# ---- routing, review of the first pass (ticket 1633) ----------------------------------------

# 1. Safety before compatibility: a reason that is only UNSUPPORTED never outranks a safety check.
case_project_lane_routing_a_compatibility_reason_never_outranks_a_safety_check() {
  skip_lockdiff_case "$FUNCNAME" || return
  local before
  # a committed version 1 lockfile together with a refused argument: the argument refuses
  lane_prepare "lane-safety-arg" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  : > "${LOG_FILE}"
  lane_run 'npm install clean'
  lane_unsupported_case "$FUNCNAME" install 'a refused argument beside a v1 lockfile' || return
  assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME" || return
  # ... with a private name: the private-name guard refuses
  lane_prepare "lane-safety-private" kept@1.0.0
  lane_private_store || { fail "$FUNCNAME: store"; return; }
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  jq -c '.dependencies["@p/lib"] = "^1.0.0"' "${WORK_DIR}/package.json" > "${WORK_DIR}/package.json.new"
  mv "${WORK_DIR}/package.json.new" "${WORK_DIR}/package.json"
  lane_commit
  : > "${LOG_FILE}"
  lane_run 'npm install clean@2.0.0'
  lane_unsupported_case "$FUNCNAME" install 'a private name beside a v1 lockfile' || return
  assert_err_contains_fragment 'touches the private-registry store' "$FUNCNAME" || return
  assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME" || return
  # ... with an .npmrc that is not admitted: both are compatibility reasons, both established, and NO npm of
  # the lane reads that project (only the route probe, in a scratch directory, ran) before today's gate
  lane_prepare "lane-safety-npmrc" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  printf 'strict-ssl=false\n' > "${WORK_DIR}/.npmrc"
  lane_commit
  lane_oneshot_case "$FUNCNAME" install 'is not a version 2 or 3 lockfile; .npmrc line 1' 'npm install clean@2.0.0' || return
  [[ "$(grep -c 'replace-registry-host=never' "${LANE_ONESHOT_TRACE}")" == 0 ]] || { fail "$FUNCNAME: the lane ran npm on a project whose .npmrc was not admitted ($(grep -c 'replace-registry-host=never' "${LANE_ONESHOT_TRACE}") lane runs)"; return; }
  # contrast: the same v1 lockfile with an admitted configuration is probed by the guards before the one-shot
  lane_prepare "lane-safety-guards-ran" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME" install 'is not a version 2 or 3 lockfile' 'npm install clean@2.0.0' || return
  grep -qP '^REAL\tnpm\tconfig\t.*--package-lock-only' "${LANE_ONESHOT_TRACE}" || { fail "$FUNCNAME: the guards (the effective-configuration probe of the lane's own invocation) did not run before the one-shot"; return; }
  # a committed lockfile with a path outside the tree is UNSAFE: refused, committed or not
  local how
  for how in committed uncommitted; do
    lane_prepare "lane-safety-outside-${how}" kept@1.0.0
    lane_lock kept@1.0.0 | jq -c '.packages["../outside/pkg"] = {"version":"1.0.0"}' > "${WORK_DIR}/package-lock.json"
    [[ "${how}" == committed ]] && lane_commit
    before="$(lane_digests)"
    : > "${LOG_FILE}"
    lane_run 'npm install clean@2.0.0'
    lane_unsupported_case "$FUNCNAME" install "a path outside the tree (${how})" || return
    assert_err_contains_fragment 'names a path outside the tree' "$FUNCNAME: ${how}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${how}" || return
    assert_lane_untouched "${before}" "$FUNCNAME: ${how}" || return
  done
  # mixed causes: one established (a committed v1 lockfile), one not (a manifest source in uncommitted changes): refused
  lane_prepare "lane-safety-mixed" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  jq -c '.dependencies.odd = "git+https://example.invalid/x.git"' "${WORK_DIR}/package.json" > "${WORK_DIR}/package.json.new"
  mv "${WORK_DIR}/package.json.new" "${WORK_DIR}/package.json"
  : > "${LOG_FILE}"
  lane_run 'npm install clean@2.0.0'
  lane_unsupported_case "$FUNCNAME" install 'mixed causes' || return
  assert_err_contains_fragment 'package.json differs from the committed one' "$FUNCNAME" || return
  assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME" || return
  pass "$FUNCNAME"
}

# the one-shot route where today's gate itself refuses: its refusal is the delegate's, never the lane's
case_project_lane_routing_the_one_shot_route_carries_todays_gates_own_refusal() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-oneshot-refusal" kept@1.0.0
  jq -c '.dependencies.odd = "git+https://example.invalid/x.git"' "${WORK_DIR}/package.json" > "${WORK_DIR}/package.json.new"
  mv "${WORK_DIR}/package.json.new" "${WORK_DIR}/package.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME" install 'manifest.dependencies.odd' 'npm install blockme@1.0.0' || return
  # (the comparison ran the switch-off fixture last; here the switch-on trace says what happened)
  lane_run 'npm install blockme@1.0.0'
  assert_status 104 "$FUNCNAME" || return
  [[ "$(tail -n 1 "${ERR_FILE}")" == "safe: BLOCKED npm install of blockme@1.0.0 — "* && "$(tail -n 1 "${ERR_FILE}")" != *'[lane: project]'* ]] || { fail "$FUNCNAME: the final diagnostic is not today's gate's own: $(tail -n 1 "${ERR_FILE}")"; return; }
  pass "$FUNCNAME"
}

case_project_lane_routing_a_probe_that_fails_to_load_is_a_refusal_never_missing_capabilities() {
  skip_lockdiff_case "$FUNCNAME" || return
  # the gate: a probe that exits non-zero or answers nothing
  local status
  for status in 3 1; do
    lane_prepare "lane-probe-status-${status}" kept@1.0.0
    : > "${LOG_FILE}"
    NODE_PROBE_STATUS="${status}" lane_run 'npm install clean@2.0.0'
    assert_status 100 "$FUNCNAME: probe status ${status}" || return
    assert_lane_final_line install "$FUNCNAME: probe status ${status}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: probe status ${status}" || return
  done
  # the probe itself, on a real node, against an npm whose definitions module THROWS
  local real_node="${REAL_NODE_BIN}"
  [[ -n "${real_node}" ]] || { printf '# %s: no node here for the throwing-module check\n' "$FUNCNAME"; pass "$FUNCNAME"; return; }
  local npm_dir="${CASE_DIR}/fake-npm" script="${CASE_DIR}/lane-probe.cjs" out
  mkdir -p "${npm_dir}/node_modules/@npmcli/config/lib" "${npm_dir}/node_modules/semver"
  printf '{"name":"npm","version":"11.20.0"}\n' > "${npm_dir}/package.json"
  printf 'exports.valid = (v) => v; exports.gte = () => true\n' > "${npm_dir}/node_modules/semver/index.js"
  printf 'throw new Error("cannot load")\n' > "${npm_dir}/node_modules/@npmcli/config/lib/definitions.js"
  ( source "${ROOT_DIR}/lib/gate-lib.sh"; safe_gate_lane_write_probe_script "${script}" ) || { fail "$FUNCNAME: cannot write the probe"; return; }
  out="$(printf '{"floor":"11.12.1","options":["allow-git"]}' | "${real_node}" "${script}" "${npm_dir}" capability 2>/dev/null)"
  local rc=$?
  [[ "${rc}" == 3 && -z "${out}" ]] || { fail "$FUNCNAME: a definitions module that throws answered (rc ${rc}: ${out})"; return; }
  # ... and one that loads but lacks the option is the positive "missing" answer
  printf 'exports.definitions = { cache: {}, git: {} }\n' > "${npm_dir}/node_modules/@npmcli/config/lib/definitions.js"
  out="$(printf '{"floor":"11.12.1","options":["allow-git","cache"]}' | "${real_node}" "${script}" "${npm_dir}" capability 2>/dev/null)"
  [[ "$(jq -c '.missing' <<<"${out}")" == '["allow-git"]' ]] || { fail "$FUNCNAME: a definitions module without the option did not answer 'missing' (${out})"; return; }
  pass "$FUNCNAME"
}

# A command that is not the lane's runs as with the switch off: same status, standard output and error, events.
lane_oneshot_global_equal() { # label script [VAR=value ...]
  local label="$1" script="$2" kv on_status on_out on_err on_events
  shift 2
  for kv in "$@"; do export "${kv?}"; done
  : > "${LOG_FILE}"
  lane_run "${script}"
  on_status="${STATUS}"; on_out="$(cat "${OUT_FILE}")"; on_err="$(cat "${ERR_FILE}")"; on_events="$(lane_delegation_of_log "${LOG_FILE}")"
  printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
  : > "${LOG_FILE}"
  lane_run "${script}"
  local same=1
  [[ "${STATUS}" == "${on_status}" && "$(cat "${OUT_FILE}")" == "${on_out}" && "$(cat "${ERR_FILE}")" == "${on_err}" && "$(lane_delegation_of_log "${LOG_FILE}")" == "${on_events}" ]] || same=0
  printf '{"install":{"project_lane":true}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
  for kv in "$@"; do unset "${kv%%=*}"; done
  (( same )) || { printf 'on: %s\n%s\n' "${on_status}" "${on_err}" >&2; fail "${label}: ${script} differs from the switch off"; return 1; }
  [[ -n "${on_events}" ]] || { fail "${label}: ${script}: nothing ran"; return 1; }
  return 0
}

# ---- routing, second review (ticket 1633) ------------------------------------------------------

# An npm that lacks the capabilities refuses: what selects a tool version (a lockfile of the version manager, a
# profile, the environment) cannot be established from the project, so no state of it is compared. The refusal
# says the operator can put the project on the one-shot lane. Nothing of the version manager's sources is read.
case_project_lane_routing_an_npm_without_the_capabilities_refuses() {
  skip_lockdiff_case "$FUNCNAME" || return
  local old='{"version":"10.9.2","atFloor":false,"missing":["allow-git"]}' layout
  # through a version manager, with the selection named by a committed, unchanged file: still a refusal
  lane_mise_layout "lane-cap-refuses-mise" kept@1.0.0
  printf 'tools = { node = "26" }\n' > "${WORK_DIR}/mise.toml"
  lane_commit
  jq -n --arg install "${NODE_DIR}" '{node: [{version: "26.13.1", install_path: $install, source: {type: "mise.toml", path: "mise.toml"}, active: true}]}' > "${CASE_DIR}/mise-ls.json"
  : > "${LOG_FILE}"
  NODE_CAPABILITY_JSON="${old}" lane_run 'npm install clean@2.0.0'
  lane_unsupported_case "$FUNCNAME: mise, committed selection" install 'a capability-less npm' || return
  assert_err_contains_fragment 'older than 11.12.1' "$FUNCNAME" || return
  ! grep -q '\[lane: one-shot' "${ERR_FILE}" || { fail "$FUNCNAME: one-shot line"; return; }
  assert_log_not_contains_fragment $'MISE_REACHED\tls --current --json' "$FUNCNAME" || return
  unset SAFE_TEST_PATH_MID
  # not through a version manager at all
  lane_prepare "lane-cap-refuses-plain" kept@1.0.0
  : > "${LOG_FILE}"
  NODE_CAPABILITY_JSON="${old}" lane_run 'npm install clean@2.0.0'
  lane_unsupported_case "$FUNCNAME: plain npm" install 'a capability-less npm' || return
  pass "$FUNCNAME"
}

case_project_lane_routing_capability_metadata_that_is_malformed_is_a_failed_probe() {
  skip_lockdiff_case "$FUNCNAME" || return
  local json
  for json in '{"version":"banana","atFloor":false,"missing":["allow-git"]}' '{"version":"11.20.0","atFloor":false,"missing":["not-an-option"]}' \
      '{"version":"11.20.0","atFloor":false,"missing":"allow-git"}' '[]'; do
    lane_prepare "lane-cap-malformed-${RANDOM}" kept@1.0.0
    : > "${LOG_FILE}"
    NODE_CAPABILITY_JSON="${json}" lane_run 'npm install clean@2.0.0'
    assert_status 100 "$FUNCNAME: ${json}" || return
    assert_lane_final_line install "$FUNCNAME: ${json}" || return
    assert_err_contains_fragment "the selected npm's definitions cannot be read" "$FUNCNAME: ${json}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${json}" || return
  done
  # the probe itself failing, in capability mode (the earlier status knob acted on the platform selection)
  lane_prepare "lane-cap-status" kept@1.0.0
  : > "${LOG_FILE}"
  NODE_CAPABILITY_STATUS=3 lane_run 'npm install clean@2.0.0'
  assert_status 100 "$FUNCNAME: capability status" || return
  assert_err_contains_fragment "the selected npm's definitions cannot be read" "$FUNCNAME: capability status" || return
  # and on a real node: a version that is not a version, definitions that are not a map
  [[ -n "${REAL_NODE_BIN}" ]] || { printf '# %s: no node here for the real-probe check\n' "$FUNCNAME"; pass "$FUNCNAME"; return; }
  local npm_dir="${CASE_DIR}/fake-npm" script="${CASE_DIR}/lane-probe.cjs" out rc
  mkdir -p "${npm_dir}/node_modules/@npmcli/config/lib" "${npm_dir}/node_modules/semver"
  printf 'exports.valid = (v) => /^[0-9]+\.[0-9]+\.[0-9]+$/.test(v) ? v : null; exports.gte = () => true\n' > "${npm_dir}/node_modules/semver/index.js"
  ( source "${ROOT_DIR}/lib/gate-lib.sh"; safe_gate_lane_write_probe_script "${script}" ) || { fail "$FUNCNAME: probe"; return; }
  printf 'exports.definitions = { git: {} }\n' > "${npm_dir}/node_modules/@npmcli/config/lib/definitions.js"
  printf '{"name":"npm","version":"banana"}\n' > "${npm_dir}/package.json"
  out="$(printf '{"floor":"11.12.1","options":["allow-git"]}' | "${REAL_NODE_BIN}" "${script}" "${npm_dir}" capability 2>/dev/null)"; rc=$?
  [[ "${rc}" == 3 && -z "${out}" ]] || { fail "$FUNCNAME: a version that is not a version answered (rc ${rc}: ${out})"; return; }
  printf '{"name":"npm","version":"11.20.0"}\n' > "${npm_dir}/package.json"
  printf 'exports.definitions = ["allow-git"]\n' > "${npm_dir}/node_modules/@npmcli/config/lib/definitions.js"
  out="$(printf '{"floor":"11.12.1","options":["allow-git"]}' | "${REAL_NODE_BIN}" "${script}" "${npm_dir}" capability 2>/dev/null)"; rc=$?
  [[ "${rc}" == 3 && -z "${out}" ]] || { fail "$FUNCNAME: definitions that are an array answered (rc ${rc}: ${out})"; return; }
  pass "$FUNCNAME"
}

# A host or caller npm configuration the lane cannot carry refuses, naming the setting; it is never routed.
case_project_lane_routing_an_npm_configuration_the_lane_cannot_carry_refuses_naming_it() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-config-refuses" kept@1.0.0
  lane_refusal_case "$FUNCNAME: an install strategy" install 'install-strategy nested' 'npm install clean@2.0.0' \
    'NPM_LOCKDIFF_EFFECTIVE_CONFIG_JSON={"package-lock":true,"ignore-scripts":true,"install-strategy":"nested"}' || return
  lane_prepare "lane-config-refuses-env" kept@1.0.0
  lane_refusal_case "$FUNCNAME: a registry" install 'a registry other than the canonical public one' 'npm install clean@2.0.0' \
    'npm_config_registry=https://r.example/' 'NPM_LOCKDIFF_REGISTRY_CONFIG_JSON={"registry":"https://r.example/"}' || return
  pass "$FUNCNAME"
}

# ONE decision after every check: a committed cause cannot mask a setting that would refuse on a supported project.
case_project_lane_routing_a_committed_cause_never_masks_a_refusal_found_later() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-unmasked" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  # a committed version 1 lockfile alone: today's gate
  lane_oneshot_case "$FUNCNAME: the cause alone" install 'is not a version 2 or 3 lockfile' 'npm install clean@2.0.0' || return
  # the same, with a caller setting the lane refuses on any project: the refusal wins
  lane_refusal_case "$FUNCNAME: with a refusing setting" install 'legacy-peer-deps' 'npm install clean@2.0.0' \
    'NPM_LOCKDIFF_EFFECTIVE_CONFIG_JSON={"package-lock":true,"ignore-scripts":true,"legacy-peer-deps":true}' || return
  # ... with an npm that fails its probe
  : > "${LOG_FILE}"
  NODE_CAPABILITY_STATUS=3 lane_run 'npm install clean@2.0.0'
  assert_status 100 "$FUNCNAME: a failing probe" || return
  assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: a failing probe" || return
  # each cause keeps its own text: two causes from two files name both
  lane_prepare "lane-two-causes" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  jq -c '.dependencies.odd = "git+https://example.invalid/x.git"' "${WORK_DIR}/package.json" > "${WORK_DIR}/package.json.new"
  mv "${WORK_DIR}/package.json.new" "${WORK_DIR}/package.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME: two causes" install 'is not a version 2 or 3 lockfile; manifest.dependencies.odd' 'npm install clean@2.0.0' || return
  pass "$FUNCNAME"
}

# Lockfile reasons: every one the core finds, the unsafe one wins whatever else is present.
case_project_lane_routing_a_lockfile_with_a_link_and_a_path_outside_the_tree_refuses() {
  skip_lockdiff_case "$FUNCNAME" || return
  local how before
  for how in committed uncommitted; do
    lane_prepare "lane-link-and-outside-${how}" kept@1.0.0
    lane_lock kept@1.0.0 | jq -c '.packages["node_modules/l"] = {"resolved":"packages/l","link":true} | .packages["../outside/pkg"] = {"version":"1.0.0"}' > "${WORK_DIR}/package-lock.json"
    [[ "${how}" == committed ]] && lane_commit
    before="$(lane_digests)"
    lane_refusal_case "$FUNCNAME: ${how}" install 'names a path outside the tree' 'npm install clean@2.0.0' || return
    assert_lane_untouched "${before}" "$FUNCNAME: ${how}" || return
  done
  # the lane's own core reports both
  local lock="${CASE_DIR}/both.json" out
  lane_lock kept@1.0.0 | jq -c '.packages["node_modules/l"] = {"resolved":"packages/l","link":true} | .packages["../outside/pkg"] = {"version":"1.0.0"}' > "${lock}"
  out="$("${SAFE_CORE_TEST_BIN}" project-lockfile-admit "${lock}" 2>&1)"
  [[ "$(printf '%s\n' "${out}" | grep -c '^lockfile_\|^links_')" == 2 ]] && printf '%s\n' "${out}" | grep -q '^links_not_supported' && printf '%s\n' "${out}" | grep -q '^lockfile_path_outside_tree' \
    || { fail "$FUNCNAME: the core did not report both reasons ($out)"; return; }
  # version 3 without a package map is undecodable (102), committed or not, never an unsupported version
  for how in committed uncommitted; do
    lane_prepare "lane-no-package-map-${how}" kept@1.0.0
    printf '{"name":"x","lockfileVersion":3,"requires":true}\n' > "${WORK_DIR}/package-lock.json"
    [[ "${how}" == committed ]] && lane_commit
    : > "${LOG_FILE}"
    lane_run 'npm install clean@2.0.0'
    assert_status 102 "$FUNCNAME: no package map (${how})" || return
    assert_lane_final_line install "$FUNCNAME: no package map (${how})" || return
    assert_err_contains_fragment 'has no package map' "$FUNCNAME: no package map (${how})" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: no package map (${how})" || return
  done
  pass "$FUNCNAME"
}

# mise exec -- npm <lane command>: refused, with the way out; every other inner command as without the lane.
case_project_lane_routing_mise_exec_with_a_lane_command_refuses() {
  skip_lockdiff_case "$FUNCNAME" || return
  local script
  for script in 'mise exec -- npm install clean@2.0.0' 'mise x -- npm install clean@2.0.0' 'mise -C . exec -- npm update' 'mise exec node@20 -- npm install clean@2.0.0'; do
    lane_prepare "lane-mise-refuses-${RANDOM}" kept@1.0.0
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run "${script}"
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'is not covered by the project lane: mise would run the original command after an audit that binds nothing' "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'run npm in the project directory instead (the mise shims select the same tools)' "$FUNCNAME: ${script}" || return
    [[ "$(tail -n 1 "${ERR_FILE}")" == "safe: BLOCKED npm "*" [lane: project] — "*"; details: safe explain" ]] || { fail "$FUNCNAME: ${script}: not the lane's final line"; return; }
    assert_log_not_contains_fragment $'REAL\tmise\texec' "$FUNCNAME: ${script}" || return
    assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME: ${script}" || return
  done
  pass "$FUNCNAME"
}

# The lane runs in a subshell: nothing it sets, exports or traps reaches today's gate; one reserved status hands over.
case_project_lane_routing_the_lane_runs_in_a_subshell_and_hands_over_by_status() {
  skip_lockdiff_case "$FUNCNAME" || return
  local out
  out="$(bash -c '
    source "$1/lib/gate-lib.sh"
    export KEEP=mine
    trap_before="$(trap -p INT)"
    safe_gate_project_lane_run() { export LEAK=1; LEAKTOO=2; unset KEEP; trap "echo trapped" INT; SAFE_GATE_LANE_PASS=1; return 0; }
    ( safe_gate_project_lane_in_subshell ); rc=$?
    same=different; [[ "$(trap -p INT)" == "${trap_before}" ]] && same=same
    printf "%s|%s|%s|%s|%s|%s\n" "${rc}" "${KEEP-unset}" "${LEAK-unset}" "${LEAKTOO-unset}" "${same}" "${SAFE_GATE_LANE_PASS-unset}"' _ "${ROOT_DIR}" 2>&1)"
  [[ "${out}" == "253|mine|unset|unset|same|unset" ]] || { fail "$FUNCNAME: the lane's state reached the caller (${out})"; return; }
  # a lane status that equals the reserved one is the command's failure, never a hand-over
  out="$(bash -c '
    source "$1/lib/gate-lib.sh"
    safe_gate_project_lane_run() { return 253; }
    ( safe_gate_project_lane_in_subshell ); echo "rc=$?"' _ "${ROOT_DIR}" 2>&1)"
  [[ "${out}" == "rc=1" ]] || { fail "$FUNCNAME: a lane status of 253 was not turned into a failure (${out})"; return; }
  # and any other status is the command's own
  out="$(bash -c '
    source "$1/lib/gate-lib.sh"
    safe_gate_project_lane_run() { return 104; }
    ( safe_gate_project_lane_in_subshell ); echo "rc=$?"' _ "${ROOT_DIR}" 2>&1)"
  [[ "${out}" == "rc=104" ]] || { fail "$FUNCNAME: a status of the command was changed (${out})"; return; }
  pass "$FUNCNAME"
}

# With the switch absent or false the lane's code is not entered: the delegate's environment is the one it
# always had, for a mise command too (the gate's own variables and an exported function included).
case_project_lane_routing_with_the_switch_off_the_delegate_environment_is_untouched() {
  skip_lockdiff_case "$FUNCNAME" || return
  local state='bash -c "g() { :; }; export -f g; export SAFE_GATE_MISE_EXTRA_OPT=keep SAFE_GATE_LANE_FOREIGN=theirs; '
  local mode script line
  for mode in absent false; do
    for script in 'mise --version' 'mise exec -- npm view kept' 'npm view kept' 'mise exec -- npm install -g okpkg'; do
      lane_prepare "lane-env-off-${mode}-${RANDOM}" kept@1.0.0
      if [[ "${mode}" == absent ]]; then rm -f "${HOME_DIR}/.config/safe/run/config.json"; else printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"; fi
      : > "${HOME_DIR}/.stub-log-env"
      : > "${LOG_FILE}"
      lane_run "${state}${script}\""
      line="$(grep '^ENVSAFE' "${LOG_FILE}" | tail -n 1)"
      [[ "${line}" == *'SAFE_GATE_MISE_EXTRA_OPT=keep'*  && "${line}" == *'SAFE_GATE_LANE_FOREIGN=theirs'* && "${line}" == *'BASH_FUNC_g%%'* ]] \
        || { fail "$FUNCNAME: ${mode}: ${script}: the delegate's environment changed (${line})"; return; }
      assert_err_not_contains_fragment 'project lane' "$FUNCNAME: ${mode}: ${script}" || return
    done
  done
  pass "$FUNCNAME"
}


# ---- routing, third review (ticket 1633) -------------------------------------------------------

# 1. No npm run decides the route. Global mode is today's gate's only in the plain form (-g or --global with no
# value, the predicate today's gate uses for its own global branch); every other spelling that selects or
# negates it refuses, with the plain form as the way out.
case_project_lane_routing_global_mode_is_read_from_the_arguments_in_the_plain_form_only() {
  skip_lockdiff_case "$FUNCNAME" || return
  local flags script
  for flags in '-g' '--global'; do
    lane_prepare "lane-global-plain-${RANDOM}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "npm install ${flags} clean@2.0.0"
    assert_status 0 "$FUNCNAME: ${flags}" || return
    assert_log_contains $'REAL\tnpm\tinstall\t'"${flags}"$'\tclean@2.0.0' "$FUNCNAME: ${flags}" || return
    assert_err_not_contains_fragment '[lane: project]' "$FUNCNAME: ${flags}" || return
    assert_log_not_contains_fragment $'REAL\tnpm\tconfig' "$FUNCNAME: ${flags} (an npm run decided the route)" || return
  done
  for script in 'npm install --global=false clean@2.0.0' 'npm install --global=true clean@2.0.0' 'npm install -g=true clean@2.0.0' \
      'npm install --global false clean@2.0.0' 'npm install -g true clean@2.0.0' 'npm install --no-global clean@2.0.0' \
      'npm install --location=global clean@2.0.0' 'npm install --location project clean@2.0.0' 'npm install --location=project clean@2.0.0'; do
    lane_prepare "lane-global-forms-${RANDOM}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "${script}"
    lane_unsupported_case "$FUNCNAME: ${script}" install "${script}" || return
    assert_err_contains_fragment 'use the plain form -g or --global' "$FUNCNAME: ${script}" || return
    [[ "$(lane_project_npm_runs)" == "0" ]] || { fail "$FUNCNAME: ${script}: npm ran"; return; }
  done
  # `--no-location` sets no location npm can be asked about: the front door refuses it (its own line, not the lane's)
  lane_prepare "lane-global-no-location" kept@1.0.0
  : > "${LOG_FILE}"
  lane_run 'npm install --no-location clean@2.0.0'
  assert_status 100 "$FUNCNAME: --no-location" || return
  assert_err_contains_fragment "the value of '--location'" "$FUNCNAME: --no-location" || return
  [[ "$(lane_project_npm_runs)" == "0" ]] || { fail "$FUNCNAME: --no-location: npm ran"; return; }
  # the operand after a terminator is an operand: the terminator refuses, a -g there never makes it global
  lane_prepare "lane-global-terminator" kept@1.0.0
  : > "${LOG_FILE}"
  lane_run 'npm install clean@2.0.0 -- --global false'
  lane_unsupported_case "$FUNCNAME: terminator" install 'terminator' || return
  pass "$FUNCNAME"
}

# 3. With an admitted .npmrc the one-shot decision is taken after every configuration probe (effective, parity,
# frozen, selection) has refused nothing: a committed cause cannot outrank a refusal only the frozen probe finds.
case_project_lane_routing_the_decision_comes_after_the_frozen_probe() {
  skip_lockdiff_case "$FUNCNAME" || return
  local frozen
  lane_prepare "lane-frozen-after" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  # the cause alone: today's gate
  lane_oneshot_case "$FUNCNAME: the cause alone" install 'is not a version 2 or 3 lockfile' 'npm install clean@2.0.0' || return
  for frozen in '{"package-lock":true,"ignore-scripts":true,"legacy-peer-deps":true}' '{"package-lock":true,"ignore-scripts":true,"package-lock-only":true}' \
      '{"package-lock":true,"ignore-scripts":true,"omit":["dev"]}'; do
    lane_prepare "lane-frozen-after-${RANDOM}" kept@1.0.0
    lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
    lane_commit
    : > "${LOG_FILE}"
    NPM_FROZEN_CONFIG_JSON="${frozen}" lane_run 'npm install clean@2.0.0'
    lane_unsupported_case "$FUNCNAME: ${frozen}" install "${frozen}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${frozen}" || return
    assert_log_not_contains_fragment $'REAL\tnpm\tinstall' "$FUNCNAME: ${frozen}" || return
  done
  pass "$FUNCNAME"
}

# 4. Lockfile: every reason of every entry; link containment on the resolved path; the legacy route only for a
# recognised legacy lockfile; the checks whatever the declared version.
case_project_lane_routing_lockfile_reasons_are_all_reported_and_never_depend_on_the_declared_version() {
  skip_lockdiff_case "$FUNCNAME" || return
  local how filter label
  # (a) one occurrence with several reasons: the unsafe one (an identity that cannot stand in a URL) is not hidden
  for filter in \
    '.packages["node_modules/a"] = {"version":"^1.0.0","resolved":"https://registry.npmjs.org/a/-/a-1.0.0.tgz"}' \
    '.packages["node_modules/a"] = {"version":"^1.0.0","resolved":"https://registry.npmjs.org/a/-/a-1.0.0.tgz","hasShrinkwrap":true}'; do
    for how in committed uncommitted; do
      lane_prepare "lane-reasons-${how}-${RANDOM}" kept@1.0.0
      lane_lock kept@1.0.0 | jq -c "${filter}" > "${WORK_DIR}/package-lock.json"
      [[ "${how}" == committed ]] && lane_commit
      : > "${LOG_FILE}"
      lane_run 'npm install clean@2.0.0'
      lane_unsupported_case "$FUNCNAME: ${how}" install "${filter}" || return
      assert_err_contains_fragment 'not safe to read' "$FUNCNAME: ${how}: ${filter}" || return
      assert_err_contains_fragment 'identity_invalid' "$FUNCNAME: ${how}: ${filter}" || return
      assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${how}" || return
    done
  done
  # (b) a link that looks inside the project and resolves, through a link of the filesystem, outside it
  for how in committed uncommitted; do
    lane_prepare "lane-physical-link-${how}" kept@1.0.0
    mkdir -p "${WORK_DIR}/packages" "${CASE_DIR}/outside-the-project"
    ln -s "${CASE_DIR}/outside-the-project" "${WORK_DIR}/packages/sneaky"
    lane_lock kept@1.0.0 | jq -c '.packages["node_modules/sneaky"] = {"resolved":"packages/sneaky","link":true}' > "${WORK_DIR}/package-lock.json"
    [[ "${how}" == committed ]] && lane_commit
    : > "${LOG_FILE}"
    lane_run 'npm install clean@2.0.0'
    lane_unsupported_case "$FUNCNAME: physical link, ${how}" install 'physical link' || return
    assert_err_contains_fragment 'link_outside_project' "$FUNCNAME: ${how}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${how}" || return
  done
  # ... and the same link kept inside the project is the merely unsupported kind: committed, today's gate
  lane_prepare "lane-physical-link-inside" kept@1.0.0
  mkdir -p "${WORK_DIR}/packages/real"
  printf '{"name":"real","version":"1.0.0"}\n' > "${WORK_DIR}/packages/real/package.json"
  lane_lock kept@1.0.0 | jq -c '.packages["node_modules/real"] = {"resolved":"packages/real","link":true}' > "${WORK_DIR}/package-lock.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME: link inside" install 'in-project links' 'npm install clean@2.0.0' || return
  # (c) the legacy route is for a RECOGNISED legacy lockfile only
  for label in '{"lockfileVersion":4,"packages":{"":{}}}' '{"lockfileVersion":"3","packages":{"":{}}}' '{"name":"x"}' '{"lockfileVersion":0,"dependencies":{}}'; do
    lane_prepare "lane-legacy-unknown-${RANDOM}" kept@1.0.0
    printf '%s\n' "${label}" > "${WORK_DIR}/package-lock.json"
    lane_commit
    : > "${LOG_FILE}"
    lane_run 'npm install clean@2.0.0'
    lane_unsupported_case "$FUNCNAME: ${label}" install "${label}" || return
    assert_err_contains_fragment 'of a version the lane does not recognise' "$FUNCNAME: ${label}" || return
    assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ${label}" || return
  done
  for label in '{"lockfileVersion":1,"dependencies":{}}' '{"dependencies":{}}'; do
    lane_prepare "lane-legacy-known-${RANDOM}" kept@1.0.0
    printf '%s\n' "${label}" > "${WORK_DIR}/package-lock.json"
    lane_commit
    lane_oneshot_case "$FUNCNAME: ${label}" install 'is not a version 2 or 3 lockfile' 'npm install clean@2.0.0' || return
  done
  # (d) whatever the declared version, a package map is judged: a version 1 or 4 document with a key outside the
  # tree, or a link leaving the project, is unsafe, committed or not
  for label in 1 4; do
    for how in outside link; do
      lane_prepare "lane-version-${label}-${how}" kept@1.0.0
      if [[ "${how}" == outside ]]; then
        printf '{"lockfileVersion":%s,"packages":{"":{},"../outside/pkg":{"version":"1.0.0"}}}\n' "${label}" > "${WORK_DIR}/package-lock.json"
      else
        printf '{"lockfileVersion":%s,"packages":{"":{},"node_modules/l":{"resolved":"../elsewhere","link":true}}}\n' "${label}" > "${WORK_DIR}/package-lock.json"
      fi
      lane_commit
      : > "${LOG_FILE}"
      lane_run 'npm install clean@2.0.0'
      lane_unsupported_case "$FUNCNAME: version ${label} ${how}" install "version ${label} ${how}" || return
      assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: version ${label} ${how}" || return
    done
  done
  pass "$FUNCNAME"
}

# 5. Environment variables that select where npm's configuration loader reads its files from refuse by name, before
# the environment is replaced: the lane would drop them, every probe would agree, and the plan would differ from the
# caller's own command.
case_project_lane_routing_variables_that_select_npms_configuration_refuse_by_name() {
  skip_lockdiff_case "$FUNCNAME" || return
  local name
  for name in PREFIX DESTDIR; do
    lane_prepare "lane-env-selector-${name}" kept@1.0.0
    : > "${LOG_FILE}"
    export "${name}=${CASE_DIR}/scratch-prefix"
    lane_run 'npm install clean@2.0.0'
    unset "${name}"
    lane_unsupported_case "$FUNCNAME: ${name}" install "${name}" || return
    assert_err_contains_fragment "the environment variable ${name}, which selects where npm reads its configuration from" "$FUNCNAME: ${name}" || return
    [[ "$(lane_project_npm_runs)" == "0" ]] || { fail "$FUNCNAME: ${name}: npm ran before the refusal"; return; }
  done
  # an empty value selects nothing (npm skips it); a variable that is not exported is not in npm's environment
  lane_prepare "lane-env-selector-empty" kept@1.0.0
  : > "${LOG_FILE}"
  PREFIX= NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run 'npm install clean@2.0.0'
  assert_status 0 "$FUNCNAME: empty PREFIX" || return
  pass "$FUNCNAME"
}

# 6. Cancelling the wrapper: the parent forwards the signal to the lane and waits for its terminal result, so the
# project lock is never held after the caller saw the wrapper end.
case_project_lane_routing_signalling_the_wrapper_waits_for_the_lane() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-wrapper-signal" kept@1.0.0
  local started="${HOME_DIR}/.projection-started" pidfile="${CASE_DIR}/wrapper.pid" statusfile="${CASE_DIR}/wrapper.status" bg waited=0 pid held
  rm -f "${started}" "${pidfile}" "${statusfile}"
  : > "${LOG_FILE}"
  ( NPM_PROJECTION_SLEEP=3 lane_run "npm install clean@2.0.0 & echo \$! > '${pidfile}'; wait \$!; echo \$? > '${statusfile}'" ) &
  bg=$!
  while [[ ! -e "${started}" || ! -s "${pidfile}" ]] && (( waited < 100 )); do sleep 0.1; waited=$((waited + 1)); done
  [[ -e "${started}" && -s "${pidfile}" ]] || { kill "${bg}" 2>/dev/null; fail "$FUNCNAME: the lane never reached its projection"; return; }
  pid="$(cat "${pidfile}")"
  kill -TERM "${pid}"
  waited=0
  while [[ ! -s "${statusfile}" ]] && (( waited < 200 )); do sleep 0.1; waited=$((waited + 1)); done
  [[ -s "${statusfile}" ]] || { kill "${bg}" 2>/dev/null; fail "$FUNCNAME: the wrapper never ended"; return; }
  # the instant the caller sees the wrapper end, the lane has ended: the project's lock is free
  held=0
  ( exec {lockfd}<"${WORK_DIR}" && flock -n -x "${lockfd}" ) 2>/dev/null || held=1
  wait "${bg}" 2>/dev/null
  (( ! held )) || { fail "$FUNCNAME: the project lock was still held when the wrapper ended"; return; }
  [[ "$(cat "${statusfile}")" == 143 ]] || { fail "$FUNCNAME: the wrapper's status is $(cat "${statusfile}"), not the lane's 143"; return; }
  [[ ! -e "${WORK_DIR}/node_modules" ]] || { fail "$FUNCNAME: a tree was produced"; return; }
  ! compgen -G "${TMPDIR:-/tmp}/safe-gate-project-lane.*" >/dev/null || printf '# %s: lane scratch of another run is present\n' "$FUNCNAME"
  pass "$FUNCNAME"
}

# 7. Nothing of the lane is assigned when the library is sourced, and the lane's own variables never carry an export
# attribute: the delegate's environment is the caller's, with the switch off and on a hand-over.
case_project_lane_routing_the_delegates_environment_keeps_the_callers_values() {
  skip_lockdiff_case "$FUNCNAME" || return
  local state='bash -c "export SAFE_GATE_HANDOVER_STATUS=mine npm_test_family=mine lane_rc=mine; ' mode script line
  for mode in absent false; do
    for script in 'npm view kept' 'mise --version'; do
      lane_prepare "lane-env-sentinel-${mode}-${RANDOM}" kept@1.0.0
      if [[ "${mode}" == absent ]]; then rm -f "${HOME_DIR}/.config/safe/run/config.json"; else printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"; fi
      : > "${HOME_DIR}/.stub-log-env"
      : > "${LOG_FILE}"
      lane_run "${state}${script}\""
      line="$(grep '^ENVSAFE' "${LOG_FILE}" | tail -n 1)"
      [[ "${line}" == *'SAFE_GATE_HANDOVER_STATUS=mine'* && "${line}" == *'npm_test_family=mine'* && "${line}" == *'lane_rc=mine'* ]] \
        || { fail "$FUNCNAME: ${mode}: ${script}: a caller's exported value was replaced (${line})"; return; }
    done
  done
  # the switch on, on a hand-over to today's gate: the same values reach it (equal to the switch off)
  lane_prepare "lane-env-sentinel-handover" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME: hand-over" install 'is not a version 2 or 3 lockfile' 'npm install clean@2.0.0' \
    SAFE_GATE_HANDOVER_STATUS=mine npm_test_family=mine lane_rc=mine || return
  line="$(grep '^ENVSAFE' "${LANE_ONESHOT_TRACE}" | tail -n 1)"
  [[ "${line}" == *'SAFE_GATE_HANDOVER_STATUS=mine'* && "${line}" == *'npm_test_family=mine'* && "${line}" == *'lane_rc=mine'* ]] \
    || { fail "$FUNCNAME: a hand-over replaced a caller's exported value (${line})"; return; }
  # the library assigns nothing when it is sourced
  [[ "$(env -i bash -c 'source "$1/lib/gate-lib.sh"; printf "%s" "${SAFE_GATE_HANDOVER_STATUS-unset}"' _ "${ROOT_DIR}" 2>/dev/null)" == unset ]] \
    || { fail "$FUNCNAME: sourcing the library assigned the hand-over status"; return; }
  pass "$FUNCNAME"
}


# ---- ci, dedupe and prune on the lane (ticket 1634) ---------------------------------------------

# Nothing was installed or published by a command that stopped before its frozen installation: the
# frozen check (`npm ci --dry-run`) may have run, no `npm ci` of the binder did.
assert_lane_ci_not_installed() {
  local label="$1"
  ! grep -q $'^CILOCK\t' "${LOG_FILE}" || { fail "${label}: the frozen installation ran"; return 1; }
  [[ ! -e "${WORK_DIR}/node_modules" ]] || { fail "${label}: a tree was produced"; return 1; }
  return 0
}

# A consistent graph, the way npm builds one: the lockfile's entries are exactly the root's dependencies (a
# `name@version:dev` spec is a devDependency), declared in the manifest and in the lockfile's root, every entry
# reachable through a declared edge. Writes the manifest and the lockfile (committed unless LANE_UNCOMMITTED=1).
lane_consistent_graph() { # <specs...>
  local spec name version deps='{}' devdeps='{}'
  for spec in "$@"; do
    name="${spec%%@*}"
    version="${spec#*@}"
    version="${version%%:*}"
    if [[ "${spec}" == *:dev ]]; then
      devdeps="$(jq -c --arg n "${name}" --arg v "${version}" '. + {($n): $v}' <<<"${devdeps}")"
    else
      deps="$(jq -c --arg n "${name}" --arg v "${version}" '. + {($n): $v}' <<<"${deps}")"
    fi
  done
  jq -nc --argjson d "${deps}" --argjson dd "${devdeps}" '{name: "lane-test", version: "1.0.0", dependencies: $d}
    + (if ($dd | length) > 0 then {devDependencies: $dd} else {} end)' > "${WORK_DIR}/package.json"
  lane_lock "$@" | jq -c --argjson d "${deps}" --argjson dd "${devdeps}" '.packages[""] += {dependencies: $d}
    + (if ($dd | length) > 0 then {devDependencies: $dd} else {} end)' > "${WORK_DIR}/package-lock.json"
  [[ "${LANE_UNCOMMITTED:-0}" == 1 ]] || lane_commit
}

# What the real npm says about the fixture in WORK_DIR, with its offline modules: the frozen validation accepts
# the lockfile, and the ideal tree holds every entry the case asserts was installed (a lockfile entry that no
# declared edge reaches is NOT in it). $@ the expected tree locations; OMIT_JSON the omissions. Skips, and
# says so, where no node with an npm is at hand.
lane_fixture_is_what_npm_builds() { # <label> <locations...>
  local label="$1" out rc
  shift
  out="$(lane_fixture_npm_verdict "$@")"; rc=$?
  case "${rc}" in
    0) return 0 ;;
    77) printf '# %s: no node with an npm here; the fixture was not checked against npm'"'"'s offline modules\n' "${label}"; return 0 ;;
    *) printf '%s\n' "${out}" >&2; fail "${label}: the fixture is not what npm would build (${out})"; return 1 ;;
  esac
}

# The verdict itself: prints npm's findings; returns 0 (a consistent graph), 77 (no npm to ask), other (not).
lane_fixture_npm_verdict() { # <locations...>
  local npm_dir="" script="${CASE_DIR}/fixture-check.cjs" out rc expected
  [[ -n "${REAL_NODE_BIN}" ]] && npm_dir="$(cd -- "$(dirname -- "${REAL_NODE_BIN}")/../lib/node_modules/npm" 2>/dev/null && pwd -P)" || npm_dir=""
  if [[ -z "${npm_dir}" || ! -f "${npm_dir}/node_modules/@npmcli/arborist/lib/index.js" ]]; then
    return 77
  fi
  cat > "${script}" <<'JS'
'use strict'
const path = require('path')
const [npmDir, dir, expectJson, omitJson, cacheDir] = process.argv.slice(2)
const Arborist = require(path.join(npmDir, 'node_modules', '@npmcli', 'arborist'))
const validate = require(path.join(npmDir, 'lib', 'utils', 'validate-lockfile.js'))
const opts = { path: dir, packageLock: true, save: false, offline: true, cache: cacheDir, omit: JSON.parse(omitJson), ignoreScripts: true }
;(async () => {
  const virtual = new Arborist(opts)
  await virtual.loadVirtual()
  const ideal = new Arborist(opts)
  await ideal.buildIdealTree()
  const errors = validate(new Map(virtual.virtualTree.inventory), new Map(ideal.idealTree.inventory))
  const have = new Set([...ideal.idealTree.inventory.values()].filter((n) => !n.isRoot).map((n) => n.location))
  const missing = JSON.parse(expectJson).filter((l) => !have.has(l))
  if (errors.length || missing.length) {
    console.log(JSON.stringify({ errors, missing }))
    process.exit(1)
  }
})().catch((e) => { console.log(JSON.stringify({ error: `${e.code}: ${e.message}` })); process.exit(2) })
JS
  expected="$(printf '%s\n' "$@" | jq -R . | jq -sc .)"
  out="$("${REAL_NODE_BIN}" "${script}" "${npm_dir}" "${WORK_DIR}" "${expected}" "${OMIT_JSON:-[]}" "${CASE_DIR}/fixture-npm-cache" 2>&1)"; rc=$?
  printf '%s' "${out}"
  return "${rc}"
}

# A project the way a fresh clone has it: its lockfile committed, no tree.
lane_fresh_clone() { # <case> <lockfile specs...>
  local name="$1"
  shift
  lane_prepare "${name}" "$@"
  lane_consistent_graph "$@"
  local clone="${CASE_DIR}/clone"
  rm -rf "${clone}"
  git clone -q "${WORK_DIR}" "${clone}" >/dev/null 2>&1 || { fail "${name}: cannot clone"; return 1; }
  WORK_DIR="${clone}"
  return 0
}

# 1. ci in a fresh clone: no projection, the lockfile on disk is the plan and (committed) the baseline, so
# its advisories are reported and never gate; the evidence request covers the WHOLE graph; the binder runs
# the frozen `npm ci` once, in staging.
case_project_lane_ci_in_a_fresh_clone_passes_on_the_advisories_its_lockfile_carries() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_fresh_clone "lane-ci-fresh" kept@1.0.0 vuln@1.0.0 risky@1.0.0 || return
  lane_fixture_is_what_npm_builds "$FUNCNAME" node_modules/kept node_modules/vuln node_modules/risky || return
  local lock
  lock="$(cat "${WORK_DIR}/package-lock.json")"
  SAFE_AUDIT_EVIDENCE_HITS="{\"vuln@1.0.0\":${LANE_HIT_CRITICAL},\"risky@1.0.0\":${LANE_HIT_HIGH}}" lane_run 'npm ci'
  assert_status 0 "$FUNCNAME" || return
  assert_err_contains_fragment 'npm ci: 3 entries of the lockfile checked for malice' "$FUNCNAME" || return
  assert_err_contains_fragment 'baseline: committed' "$FUNCNAME" || return
  assert_err_contains_fragment '2 advisories already present (critical 1, high 1)' "$FUNCNAME" || return
  assert_err_contains_fragment 'advisories: 0 fixed, 2 already present (highest: critical)' "$FUNCNAME" || return
  assert_err_contains_fragment 'installs 3 entries of the lockfile as they stand' "$FUNCNAME" || return
  # no projection: the plan is the lockfile on disk, checked by npm's own frozen check
  assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME" || return
  grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: no frozen check"; return; }
  # the whole graph is read, not a difference
  assert_log_contains $'EVIDENCE_INPUT\t["kept@1.0.0","risky@1.0.0","vuln@1.0.0"]' "$FUNCNAME" || return
  assert_log_contains $'EVIDENCE_NAMES\t["kept","risky","vuln"]' "$FUNCNAME" || return
  # one frozen installation, in staging, and nothing that resolves
  [[ "$(grep -cP '^REAL\tnpm\tci\t(?!--dry-run)' "${LOG_FILE}")" == 1 ]] || { fail "$FUNCNAME: not exactly one frozen ci"; return; }
  assert_log_not_contains_fragment $'REAL\tnpm\tinstall' "$FUNCNAME" || return
  assert_log_not_contains_fragment $'REAL\tnpm\tupdate' "$FUNCNAME" || return
  grep -q $'^CICWD\t.safe-bind-' "${LOG_FILE}" || { fail "$FUNCNAME: ci did not run in staging"; return; }
  [[ "$(cat "${WORK_DIR}/package-lock.json")" == "${lock}" ]] || { fail "$FUNCNAME: the lockfile changed"; return; }
  jq -e '.version == "1.0.0"' "${WORK_DIR}/node_modules/vuln/package.json" >/dev/null || { fail "$FUNCNAME: tree"; return; }
  # a clear ci records its lockfile as judged, like the other verbs
  [[ "$(lane_stored_digest)" == "$(lane_digest_of "${WORK_DIR}/package-lock.json")" ]] || { fail "$FUNCNAME: the judged lockfile was not recorded"; return; }
  assert_lane_no_leftover "$FUNCNAME" || return
  pass "$FUNCNAME"
}

# Malice is read over everything, whatever the baseline carries: a known-malware record or a blocklisted name
# anywhere in the graph refuses 104 and nothing is installed.
case_project_lane_ci_blocks_on_malice_anywhere_in_the_graph() {
  skip_lockdiff_case "$FUNCNAME" || return
  local kind
  for kind in malware blocklist; do
    lane_fresh_clone "lane-ci-malice-${kind}" kept@1.0.0 old@1.0.0 deep@1.0.0 || return
    lane_fixture_is_what_npm_builds "$FUNCNAME: ${kind}" node_modules/kept node_modules/old node_modules/deep || return
    if [[ "${kind}" == malware ]]; then
      SAFE_AUDIT_EVIDENCE_HITS='{"old@1.0.0":[{"id":"MAL-2026-0001","severity":"critical","malware":true}]}' lane_run 'npm ci'
      assert_err_contains_fragment 'known-malware record on old@1.0.0' "$FUNCNAME: ${kind}" || return
    else
      SAFE_AUDIT_EVIDENCE_BLOCKLIST='[{"name":"deep","reason":"operator blocklist"}]' lane_run 'npm ci'
      assert_err_contains_fragment 'blocklist entry on deep@1.0.0' "$FUNCNAME: ${kind}" || return
    fi
    assert_status 104 "$FUNCNAME: ${kind}" || return
    assert_lane_final_line ci "$FUNCNAME: ${kind}" || return
    assert_lane_ci_not_installed "$FUNCNAME: ${kind}" || return
    [[ "$(lane_stored_digest)" == none ]] || { fail "$FUNCNAME: ${kind}: a refusal recorded a baseline"; return; }
  done
  # a high advisory the committed lockfile already carries does not stop it, a critical one neither (the
  # fresh-clone case above), and a blocking severity configured by the operator still does not apply to
  # what the baseline carries
  pass "$FUNCNAME"
}

# A lockfile on disk that is neither the committed one nor a recorded one is judged against the committed one:
# what it adds is introduced.
case_project_lane_ci_with_a_lockfile_that_is_not_the_baseline_is_judged_against_the_committed_one() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-edited" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  LANE_UNCOMMITTED=1 lane_consistent_graph kept@1.0.0 vuln@1.0.0
  lane_fixture_is_what_npm_builds "$FUNCNAME" node_modules/kept node_modules/vuln || return
  local before
  before="$(lane_digests)"
  SAFE_AUDIT_EVIDENCE_HITS="{\"vuln@1.0.0\":${LANE_HIT_CRITICAL}}" lane_run 'npm ci'
  assert_status 104 "$FUNCNAME" || return
  assert_lane_final_line ci "$FUNCNAME" || return
  assert_err_contains_fragment 'baseline: the lockfile committed at the head of the git work tree' "$FUNCNAME" || return
  assert_err_contains_fragment 'the lockfile on disk is not the baseline: 1 entries added on disk and kept in the judged target were judged as introduced' "$FUNCNAME" || return
  assert_err_contains_fragment 'vuln@1.0.0 carries GHSA-crit-0001 (critical)' "$FUNCNAME" || return
  assert_lane_ci_not_installed "$FUNCNAME" || return
  assert_lane_untouched "${before}" "$FUNCNAME" || return
  # the same edit, clean: judged as introduced, passes, and the lockfile published is then a baseline
  : > "${LOG_FILE}"
  lane_run 'npm ci'
  assert_status 0 "$FUNCNAME: clean edit" || return
  assert_err_contains_fragment 'npm ci: 2 entries of the lockfile checked for malice' "$FUNCNAME" || return
  assert_err_contains_fragment 'installs 2 entries of the lockfile as they stand' "$FUNCNAME" || return
  [[ "$(lane_stored_digest)" == "$(lane_digest_of "${WORK_DIR}/package-lock.json")" ]] || { fail "$FUNCNAME: the judged lockfile was not recorded"; return; }
  # a recorded lockfile is the baseline of itself: the next ci introduces nothing, whatever it carries
  : > "${LOG_FILE}"
  SAFE_AUDIT_EVIDENCE_HITS="{\"vuln@1.0.0\":${LANE_HIT_CRITICAL}}" lane_run 'npm ci'
  assert_status 0 "$FUNCNAME: recorded" || return
  assert_err_contains_fragment 'baseline: a lockfile safe judged clear and recorded for this project' "$FUNCNAME" || return
  assert_err_contains_fragment '1 advisories already present (critical 1)' "$FUNCNAME" || return
  pass "$FUNCNAME"
}

# ci stays ci: an existing tree is replaced by the verified staged one, never updated in place; a tree that does
# not verify leaves the old one; nothing but the frozen command runs after the check.
case_project_lane_ci_on_an_existing_tree_replaces_it_and_stays_frozen() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-tree" kept@1.0.0 clean@2.0.0
  lane_consistent_graph kept@1.0.0 clean@2.0.0
  lane_fixture_is_what_npm_builds "$FUNCNAME" node_modules/kept node_modules/clean || return
  mkdir -p "${WORK_DIR}/node_modules/old"
  printf '{"name":"old","version":"1.0.0"}\n' > "${WORK_DIR}/node_modules/old/package.json"
  NPM_CI_SKIP='node_modules/clean' lane_run 'npm ci'
  assert_status 100 "$FUNCNAME: unverified" || return
  [[ -f "${WORK_DIR}/node_modules/old/package.json" && ! -e "${WORK_DIR}/node_modules/clean" ]] || { fail "$FUNCNAME: the old tree was lost to an unverified one"; return; }
  : > "${LOG_FILE}"
  lane_run 'npm ci'
  assert_status 0 "$FUNCNAME" || return
  [[ ! -e "${WORK_DIR}/node_modules/old" && -f "${WORK_DIR}/node_modules/clean/package.json" ]] || { fail "$FUNCNAME: the verified tree is not in place"; return; }
  grep -qP '^REAL\tnpm\tci\t--ignore-scripts\t--no-audit\t--no-fund\t' "${LOG_FILE}" || { fail "$FUNCNAME: no frozen ci"; return; }
  assert_log_not_contains_fragment $'REAL\tnpm\tinstall' "$FUNCNAME" || return
  assert_log_not_contains_fragment $'REAL\tnpm\tupdate' "$FUNCNAME" || return
  assert_lane_no_leftover "$FUNCNAME" || return
  # the selection of the original command carries to the frozen installation
  lane_prepare "lane-ci-omit" kept@1.0.0 dev@1.0.0:dev
  lane_consistent_graph kept@1.0.0 dev@1.0.0:dev
  OMIT_JSON='["dev"]' lane_fixture_is_what_npm_builds "$FUNCNAME: omit" node_modules/kept || return
  NPM_LOCKDIFF_EFFECTIVE_CONFIG_JSON='{"package-lock":true,"ignore-scripts":true,"omit":["dev"]}' lane_run 'npm ci --omit=dev'
  assert_status 0 "$FUNCNAME: omit" || return
  grep -qP '^REAL\tnpm\tci\t--ignore-scripts\t--no-audit\t--no-fund\t.*--omit=dev' "${LOG_FILE}" || { fail "$FUNCNAME: --omit=dev did not reach the frozen installation"; return; }
  [[ ! -e "${WORK_DIR}/node_modules/dev" && -d "${WORK_DIR}/node_modules/kept" ]] || { fail "$FUNCNAME: the omission was not applied"; return; }
  pass "$FUNCNAME"
}

# --dry-run decides and reports and writes nothing; --package-lock-only is a combination npm does not define.
case_project_lane_ci_dry_run_decides_and_package_lock_only_refuses() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-dry" kept@1.0.0 vuln@1.0.0
  lane_consistent_graph kept@1.0.0 vuln@1.0.0
  local before
  before="$(lane_digests)"
  SAFE_AUDIT_EVIDENCE_HITS="{\"vuln@1.0.0\":${LANE_HIT_CRITICAL}}" lane_run 'npm ci --dry-run'
  assert_status 0 "$FUNCNAME" || return
  assert_err_contains_fragment 'npm ci: 2 entries of the lockfile checked for malice' "$FUNCNAME" || return
  assert_err_contains_fragment 'nothing was written to the project' "$FUNCNAME" || return
  assert_lane_ci_not_installed "$FUNCNAME" || return
  assert_lane_untouched "${before}" "$FUNCNAME" || return
  [[ "$(lane_stored_digest)" == none ]] || { fail "$FUNCNAME: a dry run recorded a baseline"; return; }
  # the decision is real: malice refuses a dry run too
  : > "${LOG_FILE}"
  SAFE_AUDIT_EVIDENCE_HITS='{"vuln@1.0.0":[{"id":"MAL-2026-0001","severity":"critical","malware":true}]}' lane_run 'npm ci --dry-run'
  assert_status 104 "$FUNCNAME: dry run with malice" || return
  # package-lock-only: refused as undefined, before any npm run
  : > "${LOG_FILE}"
  lane_run 'npm ci --package-lock-only'
  lane_unsupported_case "$FUNCNAME" ci 'ci with --package-lock-only' || return
  assert_err_contains_fragment 'a combination npm does not define' "$FUNCNAME" || return
  assert_lane_untouched "${before}" "$FUNCNAME" || return
  pass "$FUNCNAME"
}

# An entry that cannot be bound refuses before npm runs, in the lane's form; npm's own refusals (a manifest out of
# step with its lockfile, a missing lockfile) stay recognisable as npm's: its diagnostic and its status.
case_project_lane_ci_refuses_before_npm_for_an_unbound_entry_and_leaves_npms_own_errors_npms() {
  skip_lockdiff_case "$FUNCNAME" || return
  # an unbound entry that exists only in uncommitted changes: refused before any npm run of the lane
  lane_prepare "lane-ci-unbound" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.packages["node_modules/bad"] = {"version":"1.0.0","resolved":"https://evil.example/bad.tgz","integrity":"sha512-AAAA"}' > "${WORK_DIR}/package-lock.json"
  lane_run 'npm ci'
  lane_unsupported_case "$FUNCNAME: unbound" ci 'an unbound entry' || return
  assert_lane_ci_not_installed "$FUNCNAME: unbound" || return
  assert_log_not_contains_fragment $'REAL\tnpm\tci' "$FUNCNAME: unbound" || return
  # manifest and lockfile out of step: npm's own error, its status, nothing judged and nothing installed
  lane_prepare "lane-ci-sync" kept@1.0.0
  : > "${LOG_FILE}"
  NPM_CI_CHECK_STATUS=1 lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: sync" || return
  assert_err_contains_fragment 'npm: code EUSAGE' "$FUNCNAME: sync" || return
  assert_err_contains_fragment 'can only install packages when your package.json and package-lock.json' "$FUNCNAME: sync" || return
  assert_err_not_contains_fragment '[--install-strategy' "$FUNCNAME: sync (npm's usage text shown)" || return
  assert_err_contains_fragment "Invalid: lock file's kept@1.0.0 does not satisfy kept@^2.0.0" "$FUNCNAME: sync" || return
  assert_lane_final_line ci "$FUNCNAME: sync" || return
  assert_err_contains_fragment "npm's own frozen check failed with npm exit 1" "$FUNCNAME: sync" || return
  assert_lane_ci_not_installed "$FUNCNAME: sync" || return
  assert_log_not_contains_fragment 'EVIDENCE_INPUT' "$FUNCNAME: sync (evidence was read for a plan npm refused)" || return
  # no lockfile at all: npm's error again
  lane_prepare "lane-ci-nolock" kept@1.0.0
  rm -f "${WORK_DIR}/package-lock.json"
  : > "${LOG_FILE}"
  lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: no lockfile" || return
  assert_err_contains_fragment 'can only install with an existing package-lock.json' "$FUNCNAME: no lockfile" || return
  assert_lane_ci_not_installed "$FUNCNAME: no lockfile" || return
  pass "$FUNCNAME"
}

# dedupe and prune: the plan is obtained as the lane obtains it (the original arguments, lockfile only, in a
# scratch copy), judged and bound like install: the frozen installation of the judged lockfile is what builds the
# tree, and the old differential path is not entered.
case_project_lane_dedupe_and_prune_are_judged_and_bound_like_install() {
  skip_lockdiff_case "$FUNCNAME" || return
  local verb target dup_lock
  # dedupe: a nested copy goes, the plan is a changed lockfile
  dup_lock="$(lane_lock kept@1.0.0 dup@1.1.0 | jq -c --argjson old "$(lane_lock dup@1.0.0 | jq -c '.packages["node_modules/dup"]')" '.packages["node_modules/kept/node_modules/dup"] = $old')"
  for verb in dedupe prune; do
    lane_prepare "lane-${verb}-bound" kept@1.0.0 dup@1.1.0
    printf '%s\n' "${dup_lock}" > "${WORK_DIR}/package-lock.json"
    lane_commit
    mkdir -p "${WORK_DIR}/node_modules/kept/node_modules/dup"
    printf '{"name":"dup","version":"1.0.0"}\n' > "${WORK_DIR}/node_modules/kept/node_modules/dup/package.json"
    target="$(lane_lock kept@1.0.0 dup@1.1.0)"
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="${target}" lane_run "npm ${verb}"
    assert_status 0 "$FUNCNAME: ${verb}" || return
    grep -qP "^PROJECTION\tnpm\t--package-lock-only\t--ignore-scripts\t--no-audit\t--no-fund\t.*\t${verb}\$" "${LOG_FILE}" || { fail "$FUNCNAME: ${verb}: the projection's command line"; return; }
    assert_err_contains_fragment '0 packages added, 1 changed, 0 removed' "$FUNCNAME: ${verb}" || return
    # nothing the old path does: no per-artifact audit, no scan of a scratch project, no delegated verb
    assert_log_not_contains_fragment $'REAL\tnpm\t'"${verb}" "$FUNCNAME: ${verb}" || return
    assert_no_per_root_audit "$FUNCNAME: ${verb}" || return
    assert_lane_scan_only_after_npm "$FUNCNAME: ${verb}" || return
    grep -qP '^REAL\tnpm\tci\t--ignore-scripts\t--no-audit\t--no-fund\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb}: no frozen ci"; return; }
    [[ "$(cat "${WORK_DIR}/package-lock.json")" == "${target}" ]] || { fail "$FUNCNAME: ${verb}: lockfile is not the judged one"; return; }
    [[ -f "${WORK_DIR}/node_modules/dup/package.json" && ! -e "${WORK_DIR}/node_modules/kept/node_modules" ]] || { fail "$FUNCNAME: ${verb}: the tree is not the judged plan"; return; }
    assert_lane_no_leftover "$FUNCNAME: ${verb}" || return
    # the selection of the original command carries to the frozen installation
    lane_prepare "lane-${verb}-omit" kept@1.0.0 dev@1.0.0:dev
    NPM_LOCKDIFF_EFFECTIVE_CONFIG_JSON='{"package-lock":true,"ignore-scripts":true,"omit":["dev"]}' \
      NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 dev@1.0.0:dev)" lane_run "npm ${verb} --omit=dev"
    assert_status 0 "$FUNCNAME: ${verb} --omit=dev" || return
    grep -qP '^REAL\tnpm\tci\t.*--omit=dev' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb}: --omit=dev did not reach the frozen installation"; return; }
    [[ ! -e "${WORK_DIR}/node_modules/dev" ]] || { fail "$FUNCNAME: ${verb}: the omission was not applied"; return; }
  done
  # a prune that changes only the tree: the lockfile is the plan, nothing is introduced, the frozen installation
  # of the same lockfile yields the pruned tree
  lane_prepare "lane-prune-tree-only" kept@1.0.0
  mkdir -p "${WORK_DIR}/node_modules/stray"
  printf '{"name":"stray","version":"9.9.9"}\n' > "${WORK_DIR}/node_modules/stray/package.json"
  local lock_before
  lock_before="$(cat "${WORK_DIR}/package-lock.json")"
  NPM_LOCK_MUTATION_JSON="${lock_before}" lane_run 'npm prune'
  assert_status 0 "$FUNCNAME: tree only" || return
  assert_err_contains_fragment '0 packages added, 0 changed, 0 removed' "$FUNCNAME: tree only" || return
  [[ ! -e "${WORK_DIR}/node_modules/stray" && -d "${WORK_DIR}/node_modules/kept" ]] || { fail "$FUNCNAME: the stray package was not pruned"; return; }
  [[ "$(cat "${WORK_DIR}/package-lock.json")" == "${lock_before}" ]] || { fail "$FUNCNAME: the lockfile changed"; return; }
  pass "$FUNCNAME"
}

# An advisory a dedupe or prune INTRODUCES (a different version of a name) is judged as introduced and refused;
# one the project already carries is not.
case_project_lane_dedupe_with_an_introduced_advisory_is_refused() {
  skip_lockdiff_case "$FUNCNAME" || return
  local verb before
  for verb in dedupe prune; do
    lane_prepare "lane-${verb}-introduced" kept@1.0.0 dup@1.0.0
    before="$(lane_digests)"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 dup@1.1.0)" SAFE_AUDIT_EVIDENCE_HITS="{\"dup@1.1.0\":${LANE_HIT_CRITICAL}}" lane_run "npm ${verb}"
    assert_status 104 "$FUNCNAME: ${verb}" || return
    assert_lane_final_line "${verb}" "$FUNCNAME: ${verb}" || return
    assert_err_contains_fragment 'dup@1.1.0 carries GHSA-crit-0001 (critical)' "$FUNCNAME: ${verb}" || return
    assert_lane_untouched "${before}" "$FUNCNAME: ${verb}" || return
    assert_log_not_contains_fragment $'REAL\tnpm\tci' "$FUNCNAME: ${verb}" || return
  done
  # --dry-run decides and writes nothing; --package-lock-only publishes the judged files and installs nothing
  lane_prepare "lane-dedupe-modes" kept@1.0.0 dup@1.0.0
  before="$(lane_digests)"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run 'npm dedupe --dry-run'
  assert_status 0 "$FUNCNAME: dry run" || return
  assert_lane_untouched "${before}" "$FUNCNAME: dry run" || return
  : > "${LOG_FILE}"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run 'npm dedupe --package-lock-only'
  assert_status 0 "$FUNCNAME: lock only" || return
  [[ "$(cat "${WORK_DIR}/package-lock.json")" == "$(lane_lock kept@1.0.0)" && ! -e "${WORK_DIR}/node_modules" ]] || { fail "$FUNCNAME: lock only"; return; }
  assert_log_not_contains_fragment $'REAL\tnpm\tci' "$FUNCNAME: lock only" || return
  pass "$FUNCNAME"
}

# The routing rows of ci, dedupe and prune: an established shape the lane cannot judge goes one-shot for ci (today's
# gate); dedupe and prune have no gate to go to, so they refuse; everything else refuses.
case_project_lane_routing_ci_dedupe_and_prune_follow_the_routing_rule() {
  skip_lockdiff_case "$FUNCNAME" || return
  local verb
  # ci, a committed version 1 lockfile: one-shot, today's gate, the line, no lane install
  lane_prepare "lane-route-ci-oneshot" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_commit
  lane_oneshot_case "$FUNCNAME: ci" ci 'is not a version 2 or 3 lockfile' 'npm ci' || return
  # the same shape in uncommitted changes: refusal
  lane_prepare "lane-route-ci-dirty" kept@1.0.0
  lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
  lane_run 'npm ci'
  lane_unsupported_case "$FUNCNAME: ci dirty" ci 'a dirty v1 lockfile' || return
  assert_err_not_contains_fragment '[lane: one-shot' "$FUNCNAME: ci dirty" || return
  # dedupe and prune: the established shape takes the one-shot route like install, and that route is today's older differential
  # path, which judges them where it can and refuses the rest with its own line (no override of its own)
  for verb in dedupe prune; do
    lane_prepare "lane-route-${verb}-oneshot" kept@1.0.0
    lane_lock kept@1.0.0 | jq -c '.lockfileVersion = 1' > "${WORK_DIR}/package-lock.json"
    lane_commit
    : > "${LOG_FILE}"
    lane_run "npm ${verb}"
    assert_err_contains_fragment '[lane: one-shot, the committed lockfile is not a version 2 or 3 lockfile' "$FUNCNAME: ${verb}" || return
    assert_err_contains_fragment "npm ${verb} goes to today's older differential path" "$FUNCNAME: ${verb}" || return
    assert_err_contains_fragment "BLOCKED npm ${verb} —" "$FUNCNAME: ${verb}: the older path's own refusal" || return
    ! grep -q '\[lane: project\]' "${ERR_FILE}" || { fail "$FUNCNAME: ${verb}: a lane refusal"; return; }
    assert_log_not_contains_fragment 'PROJECTION' "$FUNCNAME: ${verb}" || return
  done
  # an npm without the capabilities refuses all three
  for verb in ci dedupe prune; do
    lane_prepare "lane-route-${verb}-cap" kept@1.0.0
    : > "${LOG_FILE}"
    NODE_CAPABILITY_JSON='{"version":"10.9.2","atFloor":false,"missing":["allow-git"]}' lane_run "npm ${verb}"
    lane_unsupported_case "$FUNCNAME: ${verb} capabilities" "${verb}" 'a capability-less npm' || return
  done
  # aliases of the three verbs take the same route
  lane_prepare "lane-route-alias" kept@1.0.0
  : > "${LOG_FILE}"
  lane_run 'npm clean-install'
  assert_status 0 "$FUNCNAME: clean-install" || return
  grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: clean-install did not take the ci route"; return; }
  : > "${LOG_FILE}"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run 'npm ddp'
  assert_status 0 "$FUNCNAME: ddp" || return
  grep -q $'^PROJECTION\tnpm' "${LOG_FILE}" || { fail "$FUNCNAME: ddp did not take the dedupe route"; return; }
  pass "$FUNCNAME"
}

# With the switch ON the old differential path is never entered for a project command; with it OFF it is the
# only path (existing case_npm_*lockdiff* cases, unchanged). A global dedupe/prune goes to the old code's own
# refusal, which it makes before anything of the path runs.
case_project_lane_routing_the_old_differential_path_is_reachable_only_with_the_switch_off() {
  skip_lockdiff_case "$FUNCNAME" || return
  local verb
  for verb in dedupe prune; do
    lane_prepare "lane-oldpath-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run "npm ${verb}"
    assert_status 0 "$FUNCNAME: ${verb} on" || return
    ! compgen -G "${TMPDIR:-/tmp}/safe-gate-lockdiff.*" >/dev/null || printf '# %s: scratch of another run\n' "$FUNCNAME"
    assert_no_per_root_audit "$FUNCNAME: ${verb} on" || return
    assert_lane_scan_only_after_npm "$FUNCNAME: ${verb} on" || return
    # the same command with the switch off enters the old path: it audits the introduced set (nothing here) and
    # requires the tree it would otherwise refuse without
    printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
    rm -rf "${WORK_DIR}/node_modules"
    : > "${LOG_FILE}"
    lane_run "npm ${verb}"
    assert_status 100 "$FUNCNAME: ${verb} off" || return
    assert_err_contains_fragment 'node_modules is absent' "$FUNCNAME: ${verb} off" || return
    assert_err_not_contains_fragment '[lane: project]' "$FUNCNAME: ${verb} off" || return
  done
  # global: refused by the old code at once, with the switch on as with it off
  lane_prepare "lane-oldpath-global" kept@1.0.0
  : > "${LOG_FILE}"
  lane_run 'npm dedupe -g'
  assert_status 100 "$FUNCNAME: global" || return
  assert_err_contains_fragment 'global dependency mutations have no project lockfile to audit' "$FUNCNAME: global" || return
  pass "$FUNCNAME"
}

# The whole graph is read for ci: what that costs on a 1,000-entry lockfile with the stub reader (the live
# suite measures the real reading).
case_project_lane_ci_reads_the_whole_graph_of_a_thousand_entries() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-thousand" kept@1.0.0
  local file="${CASE_DIR}/thousand-lock.json" integrity started elapsed
  integrity="$(lane_integrity bulk)"
  # 1,000 entries: the root requires `kept` and 999 bulk packages, every entry reachable from the manifest
  jq -nc --arg i "${integrity}" --arg ki "$(lane_integrity kept@1.0.0)" '
    ([range(0; 999) | {key: "bulk-package-\(.)", value: "1.0.0"}] | from_entries + {kept: "1.0.0"}) as $deps
    | {name: "lane-test", version: "1.0.0", dependencies: $deps} as $manifest
    | {lockfileVersion: 3, requires: true,
       packages: ({"": ($manifest | {name, version, dependencies})}
         + {"node_modules/kept": {version: "1.0.0", resolved: "https://registry.npmjs.org/kept/-/kept-1.0.0.tgz", integrity: $ki}}
         + ([range(0; 999) | {key: "node_modules/bulk-package-\(.)", value: {version: "1.0.0",
             resolved: "https://registry.npmjs.org/bulk-package-\(.)/-/bulk-package-\(.)-1.0.0.tgz", integrity: $i}}] | from_entries))}' > "${file}"
  jq -c '.packages[""] | {name, version, dependencies}' "${file}" > "${WORK_DIR}/package.json"
  cp -- "${file}" "${WORK_DIR}/package-lock.json"
  lane_commit
  lane_fixture_is_what_npm_builds "$FUNCNAME" node_modules/kept node_modules/bulk-package-0 node_modules/bulk-package-998 || return
  started="${SECONDS}"
  lane_run 'npm ci'
  elapsed=$((SECONDS - started))
  assert_status 0 "$FUNCNAME" || return
  assert_err_contains_fragment 'npm ci: 1000 entries of the lockfile checked for malice' "$FUNCNAME" || return
  [[ "$(grep '^EVIDENCE_INPUT' "${LOG_FILE}" | cut -f2 | jq 'length')" == 1000 ]] || { fail "$FUNCNAME: the evidence request does not cover the whole graph"; return; }
  [[ -f "${WORK_DIR}/node_modules/bulk-package-998/package.json" ]] || { fail "$FUNCNAME: tree"; return; }
  printf '# %s: 1000 entries, whole ci command with the stub reader: %ss\n' "$FUNCNAME" "${elapsed}"
  pass "$FUNCNAME"
}



# ---- ci, dedupe and prune: the critical review (ticket 1634) ------------------------------------------

# 1. Only what npm resolves. A token the gate's conservative classifier takes for ci, dedupe, prune, install or
# update and that the selected npm does not resolve (`clean`, `install-c`, an ambiguous prefix) is left to npm,
# which rejects it: the lane does nothing with the project and refuses nothing in npm's place. With the switch on
# it goes to today's gate exactly as with the switch off.
case_project_lane_routing_a_token_npm_does_not_resolve_is_left_to_npm() {
  skip_lockdiff_case "$FUNCNAME" || return
  local token on_status on_out on_err off_status off_out off_err on_events off_events marker
  for token in clean install-c cl; do
    lane_prepare "lane-unresolved-${token}" kept@1.0.0 clean@2.0.0
    lane_consistent_graph kept@1.0.0 clean@2.0.0
    mkdir -p "${WORK_DIR}/node_modules/marker"
    printf '{"name":"marker","version":"1.0.0"}\n' > "${WORK_DIR}/node_modules/marker/package.json"
    local before
    before="$(lane_digests)"
    : > "${HOME_DIR}/.stub-log-env"
    : > "${LOG_FILE}"
    lane_run "npm ${token}"
    on_status="${STATUS}"; on_out="$(cat "${OUT_FILE}")"; on_err="$(cat "${ERR_FILE}")"; on_events="$(lane_delegation_of_log "${LOG_FILE}" "${WORK_DIR}" "<W>")"
    # the lane did nothing with the project: the tree, the lockfile and the manifest are as they were
    [[ -f "${WORK_DIR}/node_modules/marker/package.json" && "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: ${token}: the project was touched"; return; }
    ! grep -q $'^PROJECTION\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${token}: the lane projected"; return; }
    assert_log_not_contains_fragment $'REAL\tnpm\tci' "$FUNCNAME: ${token}" || return
    ! grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${token}: the lane checked"; return; }
    [[ "${on_err}" != *'[lane: project]'* && "${on_err}" != *'project lane:'* ]] || { fail "$FUNCNAME: ${token}: the lane spoke (${on_err})"; return; }
    # the same command with the switch off
    printf '{"install":{"project_lane":false}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
    : > "${LOG_FILE}"
    lane_run "npm ${token}"
    off_status="${STATUS}"; off_out="$(cat "${OUT_FILE}")"; off_err="$(cat "${ERR_FILE}")"; off_events="$(lane_delegation_of_log "${LOG_FILE}" "${WORK_DIR}" "<W>")"
    [[ "${on_status}" == "${off_status}" && "${on_out}" == "${off_out}" && "${on_err//${WORK_DIR}/<W>}" == "${off_err//${WORK_DIR}/<W>}" ]] \
      || { printf 'on: %s\n%s\noff: %s\n%s\n' "${on_status}" "${on_err}" "${off_status}" "${off_err}" >&2; fail "$FUNCNAME: ${token}: not the switch-off behaviour"; return; }
    [[ "${on_events}" == "${off_events}" ]] || { diff <(printf '%s\n' "${on_events}") <(printf '%s\n' "${off_events}") >&2; fail "$FUNCNAME: ${token}: today's gate did not run as with the switch off"; return; }
    [[ -n "${on_events}" ]] || { fail "$FUNCNAME: ${token}: nothing was delegated"; return; }
  done
  # npm's resolution, not the classifier's, decides in the other direction too: every spelling npm resolves is the lane's
  for token in ic clean-install install-clean isntall-clean ci; do
    lane_prepare "lane-resolved-${token}" kept@1.0.0
    lane_consistent_graph kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "npm ${token}"
    assert_status 0 "$FUNCNAME: ${token}" || return
    grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${token}: not the lane's ci"; return; }
  done
  # the question to npm cannot be asked: infrastructure breakage, refused in the lane's form
  lane_prepare "lane-resolve-fails" kept@1.0.0
  : > "${LOG_FILE}"
  NODE_DEREF_STATUS=3 lane_run 'npm ci'
  assert_status 100 "$FUNCNAME: probe fails" || return
  assert_lane_final_line ci "$FUNCNAME: probe fails" || return
  assert_err_contains_fragment "command resolution cannot be asked" "$FUNCNAME: probe fails" || return
  # npm resolves the token to ANOTHER command than the gate's table (a table that does not match this npm):
  # nothing says npm rejects it, so it is neither left to npm nor judged under a verb npm will not run
  local skewed
  for skewed in 'ci:install' 'dedupe:install' 'prune:dedupe' 'install:ci'; do
    lane_prepare "lane-table-skew-${skewed%%:*}" kept@1.0.0
    lane_consistent_graph kept@1.0.0
    mkdir -p "${WORK_DIR}/node_modules/marker"
    printf '{"name":"marker","version":"1.0.0"}\n' > "${WORK_DIR}/node_modules/marker/package.json"
    before="$(lane_digests)"
    : > "${LOG_FILE}"
    NODE_DEREF_COMMAND="${skewed##*:}" lane_run "npm ${skewed%%:*}"
    assert_status 100 "$FUNCNAME: table skew ${skewed}" || return
    assert_lane_final_line "${skewed%%:*}" "$FUNCNAME: table skew ${skewed}" || return
    assert_err_contains_fragment "the selected npm resolves it to npm ${skewed##*:}: safe's command table does not match this npm" "$FUNCNAME: table skew ${skewed}" || return
    [[ -f "${WORK_DIR}/node_modules/marker/package.json" && "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: table skew ${skewed}: the project was touched"; return; }
    ! grep -q $'^REAL\tnpm\t' "${LOG_FILE}" || { grep $'^REAL\t' "${LOG_FILE}" >&2; fail "$FUNCNAME: table skew ${skewed}: the command reached npm"; return; }
    ! grep -q -E $'^(PROJECTION|CICHECK)\t' "${LOG_FILE}" || { fail "$FUNCNAME: table skew ${skewed}: the lane went on"; return; }
  done
  # on a real node: npm's own resolver, not the stub's table
  if [[ -n "${REAL_NODE_BIN}" ]]; then
    local npm_dir script="${CASE_DIR}/lane-probe.cjs" out
    npm_dir="$(cd -- "$(dirname -- "${REAL_NODE_BIN}")/../lib/node_modules/npm" 2>/dev/null && pwd -P)" || npm_dir=""
    if [[ -f "${npm_dir}/lib/utils/cmd-list.js" ]]; then
      ( source "${ROOT_DIR}/lib/gate-lib.sh"; safe_gate_lane_write_probe_script "${script}" ) || { fail "$FUNCNAME: probe script"; return; }
      for token in clean install-c ic ddp dedupe; do
        out="$(printf '{"token":"%s"}' "${token}" | "${REAL_NODE_BIN}" "${script}" "${npm_dir}" deref 2>/dev/null)"
        case "${token}" in
          clean|install-c) [[ "${out}" == '{"command":null}' ]] || { fail "$FUNCNAME: real npm resolved ${token} (${out})"; return; } ;;
          ic) [[ "${out}" == '{"command":"ci"}' ]] || { fail "$FUNCNAME: real npm: ic (${out})"; return; } ;;
          ddp|dedupe) [[ "${out}" == '{"command":"dedupe"}' ]] || { fail "$FUNCNAME: real npm: ${token} (${out})"; return; } ;;
        esac
      done
    fi
  fi
  pass "$FUNCNAME"
}

# 2. Nothing stands in for npm's own dedupe. When npm's lockfile-only dedupe WROTE a lockfile that differs from the
# snapshot's, that lockfile is the plan; when it wrote none (it saves nothing when no name is duplicated), the plan is
# the lockfile on disk, byte for byte, provided npm's own frozen check accepts it (the check ci runs). A lockfile out of
# step refuses with npm's diagnostic and status; no lockfile refuses 100 (dedupe and prune); a lockfile entry the
# frozen installation does not build is caught by the binder's verification before anything is published.
case_project_lane_dedupe_judges_the_plan_npm_leaves() {
  skip_lockdiff_case "$FUNCNAME" || return
  local before target
  # (a) duplicates present: npm writes the plan; that lockfile is judged; no frozen check of the old one
  lane_prepare "lane-dedupe-dups" kept@1.0.0 dup@1.1.0
  lane_consistent_graph kept@1.0.0 dup@1.1.0
  jq -c --argjson old "$(lane_lock dup@1.0.0 | jq -c '.packages["node_modules/dup"]')" '.packages["node_modules/kept/node_modules/dup"] = $old' "${WORK_DIR}/package-lock.json" > "${WORK_DIR}/lock.new"
  mv "${WORK_DIR}/lock.new" "${WORK_DIR}/package-lock.json"
  lane_commit
  target="$(lane_lock kept@1.0.0 dup@1.1.0 | jq -c '.packages[""] += {dependencies: {kept: "1.0.0", dup: "1.1.0"}}')"
  : > "${LOG_FILE}"
  NPM_LOCK_MUTATION_JSON="${target}" lane_run 'npm dedupe'
  assert_status 0 "$FUNCNAME: duplicates" || return
  [[ "$(grep -c $'^PROJECTION\t' "${LOG_FILE}")" == 1 ]] || { fail "$FUNCNAME: duplicates: more than npm's own dedupe ran"; return; }
  ! grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: duplicates: the frozen check ran on a plan npm wrote"; return; }
  [[ "$(cat "${WORK_DIR}/package-lock.json")" == "${target}" ]] || { fail "$FUNCNAME: duplicates: the published lockfile is not npm's plan"; return; }
  # (b) nothing to do: npm saves nothing; the plan is the lockfile on disk, byte for byte, after npm's own frozen check
  lane_prepare "lane-dedupe-nothing" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  target="$(cat "${WORK_DIR}/package-lock.json")"
  : > "${LOG_FILE}"
  NPM_DEDUPE_SAVES_NOTHING=1 lane_run 'npm dedupe'
  assert_status 0 "$FUNCNAME: nothing" || return
  [[ "$(grep -c $'^PROJECTION\t' "${LOG_FILE}")" == 1 ]] || { fail "$FUNCNAME: nothing: a second lockfile step ran"; return; }
  grep -q $'^CICHECK\t' "${LOG_FILE}" || { fail "$FUNCNAME: nothing: npm's frozen check did not run"; return; }
  assert_err_contains_fragment '0 packages added, 0 changed, 0 removed' "$FUNCNAME: nothing" || return
  [[ "$(cat "${WORK_DIR}/package-lock.json")" == "${target}" ]] || { fail "$FUNCNAME: nothing: the lockfile changed"; return; }
  # (c) npm saves nothing and the lockfile is out of step with the manifest: npm's own frozen-check error and status
  lane_prepare "lane-dedupe-outofstep" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  before="$(lane_digests)"
  : > "${LOG_FILE}"
  NPM_DEDUPE_SAVES_NOTHING=1 NPM_CI_CHECK_STATUS=1 lane_run 'npm dedupe'
  assert_status 1 "$FUNCNAME: out of step" || return
  assert_lane_final_line dedupe "$FUNCNAME: out of step" || return
  assert_err_contains_fragment 'npm: code EUSAGE' "$FUNCNAME: out of step" || return
  assert_err_contains_fragment "npm's own frozen check failed with npm exit 1" "$FUNCNAME: out of step" || return
  assert_err_contains_fragment 'run npm install first' "$FUNCNAME: out of step" || return
  assert_lane_untouched "${before}" "$FUNCNAME: out of step" || return
  ! grep -q $'^EVIDENCE_INPUT' "${LOG_FILE}" || { fail "$FUNCNAME: out of step: evidence was read for a plan npm refused"; return; }
  # (d) no lockfile: dedupe and prune refuse 100 before anything is resolved (npm would work from the installed tree)
  local verb
  for verb in dedupe prune; do
    lane_prepare "lane-${verb}-nolock" kept@1.0.0
    lane_consistent_graph kept@1.0.0
    rm -f "${WORK_DIR}/package-lock.json"
    lane_commit
    before="$(sha256sum "${WORK_DIR}/package.json" | cut -d' ' -f1)"
    : > "${LOG_FILE}"
    lane_run "npm ${verb}"
    lane_unsupported_case "$FUNCNAME: ${verb} no lockfile" "${verb}" "npm ${verb} with no lockfile" || return
    assert_err_contains_fragment "npm ${verb} on a project with no lockfile" "$FUNCNAME: ${verb}" || return
    assert_err_contains_fragment 'run npm install first' "$FUNCNAME: ${verb}" || return
    ! grep -q $'^PROJECTION\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${verb}: a plan was resolved"; return; }
    [[ ! -e "${WORK_DIR}/package-lock.json" && ! -e "${WORK_DIR}/node_modules" ]] || { fail "$FUNCNAME: ${verb}: the project was touched"; return; }
  done
  # (e) a lockfile entry the frozen installation does not build (a surplus entry nothing needs): npm accepts the lockfile, its
  # `npm ci` builds only what the manifest reaches, and the binder's verification refuses BEFORE anything is published,
  # saying what to do
  lane_prepare "lane-dedupe-surplus" kept@1.0.0 old@1.0.0
  lane_consistent_graph kept@1.0.0
  lane_lock kept@1.0.0 old@1.0.0 | jq -c '.packages[""] += {dependencies: {kept: "1.0.0"}}' > "${WORK_DIR}/package-lock.json"
  lane_commit
  before="$(lane_digests)"
  : > "${LOG_FILE}"
  NPM_DEDUPE_SAVES_NOTHING=1 NPM_CI_SKIP='node_modules/old' lane_run 'npm dedupe'
  assert_status 100 "$FUNCNAME: surplus" || return
  assert_lane_final_line dedupe "$FUNCNAME: surplus" || return
  assert_err_contains_fragment 'node_modules/old: missing' "$FUNCNAME: surplus" || return
  assert_err_contains_fragment 'run npm install first to refresh it' "$FUNCNAME: surplus" || return
  assert_err_contains_fragment 'nothing was published' "$FUNCNAME: surplus" || return
  # (the binder's staged frozen installation ran; the project is as it was)
  [[ "$(lane_digests)" == "${before}" && ! -e "${WORK_DIR}/node_modules" ]] || { fail "$FUNCNAME: surplus: the project changed"; return; }
  assert_lane_no_leftover "$FUNCNAME: surplus" || return
  pass "$FUNCNAME"
}

# 3. npm's own errors, wherever they are in its output.
case_project_lane_ci_shows_npms_error_wherever_it_is_in_its_output() {
  skip_lockdiff_case "$FUNCNAME" || return
  # a missing lockfile under a verbose log level: npm's explanation and its code come after 120 lines of log
  lane_prepare "lane-ci-verbose-nolock" kept@1.0.0
  rm -f "${WORK_DIR}/package-lock.json"
  : > "${LOG_FILE}"
  NPM_CI_CHECK_NOISE=1 lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: verbose, no lockfile" || return
  assert_err_contains_fragment 'npm: code EUSAGE' "$FUNCNAME: verbose, no lockfile" || return
  assert_err_contains_fragment 'can only install with an existing package-lock.json' "$FUNCNAME: verbose, no lockfile" || return
  assert_err_not_contains_fragment 'config load:file' "$FUNCNAME: verbose, no lockfile (log noise shown)" || return
  assert_err_contains_fragment "npm's own frozen check failed with npm exit 1 (code EUSAGE)" "$FUNCNAME: verbose, no lockfile" || return
  assert_lane_final_line ci "$FUNCNAME: verbose, no lockfile" || return
  assert_lane_ci_not_installed "$FUNCNAME: verbose, no lockfile" || return
  # a platform error on a synchronised project: not a missing or out-of-step lockfile, and the final line does not say so
  lane_prepare "lane-ci-platform" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  : > "${LOG_FILE}"
  NPM_CI_CHECK_ERROR=EBADPLATFORM NPM_CI_CHECK_NOISE=1 lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: platform" || return
  assert_err_contains_fragment 'npm: code EBADPLATFORM' "$FUNCNAME: platform" || return
  assert_err_contains_fragment 'Unsupported platform for fsevents@2.3.3' "$FUNCNAME: platform" || return
  assert_err_contains_fragment "npm's own frozen check failed with npm exit 1 (code EBADPLATFORM)" "$FUNCNAME: platform" || return
  [[ "$(tail -n 1 "${ERR_FILE}")" != *'out of step'* && "$(tail -n 1 "${ERR_FILE}")" != *'missing'* ]] || { fail "$FUNCNAME: platform: the final line names a cause npm did not give"; return; }
  assert_lane_ci_not_installed "$FUNCNAME: platform" || return
  pass "$FUNCNAME"
}

# 4. prune --package-lock-only: not a caller mode of prune; the lane's own lockfile-only projection of a plain prune stays.
case_project_lane_prune_package_lock_only_refuses() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-prune-lock-only" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  local before arg
  before="$(lane_digests)"
  for arg in '--package-lock-only' '--package-lock-only=true'; do
    : > "${LOG_FILE}"
    lane_run "npm prune ${arg}"
    lane_unsupported_case "$FUNCNAME: ${arg}" prune "npm prune ${arg}" || return
    assert_err_contains_fragment 'npm prune with --package-lock-only' "$FUNCNAME: ${arg}" || return
    assert_lane_untouched "${before}" "$FUNCNAME: ${arg}" || return
  done
  # the plain prune keeps its internal lockfile-only projection, and dedupe keeps the caller mode
  : > "${LOG_FILE}"
  NPM_LOCK_MUTATION_JSON="$(cat "${WORK_DIR}/package-lock.json")" lane_run 'npm prune'
  assert_status 0 "$FUNCNAME: plain prune" || return
  grep -q $'^PROJECTION\tnpm\t--package-lock-only' "${LOG_FILE}" || { fail "$FUNCNAME: plain prune: no projection"; return; }
  pass "$FUNCNAME"
}

# 6. Smaller points: the report tells entries submitted for the malice check from identities read completely; the
# defensive guard for dedupe/prune reads the arguments up to the option terminator, as the global rule does.
case_project_lane_ci_report_does_not_overstate_incomplete_coverage_and_the_guard_uses_the_global_boundary() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-incomplete" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  : > "${LOG_FILE}"
  SAFE_AUDIT_EVIDENCE_MISSING='["kept@1.0.0"]' lane_run 'npm ci'
  assert_status 102 "$FUNCNAME: incomplete" || return
  assert_err_contains_fragment '0 of 1 identities read completely' "$FUNCNAME: incomplete" || return
  assert_err_contains_fragment '1 entries of the lockfile submitted for the malice check' "$FUNCNAME: incomplete" || return
  assert_err_not_contains_fragment 'entries of the lockfile checked for malice' "$FUNCNAME: incomplete" || return
  assert_lane_ci_not_installed "$FUNCNAME: incomplete" || return
  # the global rule's argument boundary: `npm prune -g -- --no-global` is global, handed to the old code's own refusal
  local verb
  for verb in prune dedupe; do
    lane_prepare "lane-guard-boundary-${verb}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "npm ${verb} -g -- --no-global"
    assert_status 100 "$FUNCNAME: ${verb} -g" || return
    assert_err_contains_fragment 'global dependency mutations have no project lockfile to audit' "$FUNCNAME: ${verb} -g" || return
    assert_err_not_contains_fragment 'install.sh' "$FUNCNAME: ${verb} -g" || return
  done
  pass "$FUNCNAME"
}


# 5. The checker itself: the shapes the review found are NOT what npm builds (a lockfile entry no declared edge
# reaches is not in the ideal tree; a root dependency missing from the lockfile needs resolution), and the
# consistent shapes are.
case_project_lane_the_ci_fixtures_are_checked_against_npms_offline_modules() {
  skip_lockdiff_case "$FUNCNAME" || return
  local out rc
  # the old fresh-clone shape: the manifest requires only kept, the lockfile also lists vuln and risky
  lane_prepare "lane-fixture-surplus" kept@1.0.0 vuln@1.0.0 risky@1.0.0
  out="$(lane_fixture_npm_verdict node_modules/kept node_modules/vuln node_modules/risky)"; rc=$?
  if (( rc == 77 )); then printf '# %s: no node with an npm here; the checker was not exercised\n' "$FUNCNAME"; pass "$FUNCNAME"; return; fi
  (( rc != 0 )) && [[ "${out}" == *'"missing":["node_modules/vuln","node_modules/risky"]'* ]] || { fail "$FUNCNAME: an unreachable lockfile entry was taken for installed (${rc}: ${out})"; return; }
  # the old 1,000-entry shape: the manifest requires kept, which the lockfile lacks
  lane_prepare "lane-fixture-missing-root" kept@1.0.0
  lane_lock bulk@1.0.0 > "${WORK_DIR}/package-lock.json"
  out="$(lane_fixture_npm_verdict node_modules/bulk)"; rc=$?
  (( rc != 0 )) || { fail "$FUNCNAME: a lockfile without the manifest's own dependency was accepted"; return; }
  # the consistent shape
  lane_prepare "lane-fixture-consistent" kept@1.0.0
  lane_consistent_graph kept@1.0.0 vuln@1.0.0 risky@1.0.0
  out="$(lane_fixture_npm_verdict node_modules/kept node_modules/vuln node_modules/risky)"; rc=$?
  (( rc == 0 )) || { fail "$FUNCNAME: a consistent graph was refused (${out})"; return; }
  pass "$FUNCNAME"
}


# ---- ci/dedupe/prune: the second critical review (ticket 1634) ---------------------------------------

# 1. An option before the verb refuses BEFORE npm is asked what the token resolves to: with `npm --json=prefix de`
# safe takes `de` for the command and npm takes `prefix` (npm leaves the value of a boolean flag written `--flag=word`
# as a positional), so passing `de` through as "a word npm rejects" would run a command npm does run.
case_project_lane_routing_an_option_before_the_verb_refuses_before_npm_is_asked() {
  skip_lockdiff_case "$FUNCNAME" || return
  local script before
  for script in 'npm --loglevel=error de' 'npm --loglevel=error clean' 'npm -- de' 'npm --loglevel=error ci' 'npm --loglevel=error dedupe' 'npm --loglevel=error install clean'; do
    lane_prepare "lane-option-before-${RANDOM}" kept@1.0.0
    lane_consistent_graph kept@1.0.0
    mkdir -p "${WORK_DIR}/node_modules/marker"
    printf '{"name":"marker","version":"1.0.0"}\n' > "${WORK_DIR}/node_modules/marker/package.json"
    before="$(lane_digests)"
    : > "${LOG_FILE}"
    lane_run "${script}"
    assert_status 100 "$FUNCNAME: ${script}" || return
    # the verb in the lane's line is whatever safe took the token for: only the form is asserted
    [[ "$(tail -n 1 "${ERR_FILE}")" == "safe: BLOCKED npm "*" [lane: project] — "*"; details: safe explain" && "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: ${script}: not the lane's single final line"; return; }
    assert_err_contains_fragment 'an option before the verb' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: something was delegated ($(grep '^REAL' "${LOG_FILE}" | head -n 2))"; return; }
    [[ -f "${WORK_DIR}/node_modules/marker/package.json" && "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: ${script}: the project was touched"; return; }
  done
  # the forms npm reads differently (a Boolean's value is the command) never reach the lane: the front door refuses them
  for script in 'npm --json=prefix de' 'npm --json=install de' 'npm --json=prefix clean' 'npm --json=prefix ci' 'npm --json=prefix dedupe'; do
    lane_prepare "lane-option-before-fd-${RANDOM}" kept@1.0.0
    : > "${LOG_FILE}"
    lane_run "${script}"
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'to allow: write the option without the value' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: something was delegated"; return; }
  done
  pass "$FUNCNAME"
}

# 3. npm's own error survives the caller's presentation settings: a heading, colour and a log level that hides errors
# change what npm prints; the runs whose output the lane reads carry their own heading, colour off and a log level
# that shows errors (and the capability list requires the selected npm to define them). When no error line can be
# read the cleaned end of npm's output is shown, and the final line says so.
case_project_lane_ci_error_survives_the_callers_presentation_settings() {
  skip_lockdiff_case "$FUNCNAME" || return
  local setting
  for setting in 'npm_config_heading=review-npm' 'npm_config_color=always' 'npm_config_loglevel=silent' 'npm_config_loglevel=silly'; do
    lane_prepare "lane-ci-present-${RANDOM}" kept@1.0.0
    rm -f "${WORK_DIR}/package-lock.json"
    : > "${LOG_FILE}"
    export "${setting?}"
    lane_run 'npm ci'
    unset "${setting%%=*}"
    assert_status 1 "$FUNCNAME: ${setting}" || return
    assert_err_contains_fragment 'npm: code EUSAGE' "$FUNCNAME: ${setting}" || return
    assert_err_contains_fragment 'can only install with an existing package-lock.json' "$FUNCNAME: ${setting}" || return
    assert_err_contains_fragment "npm's own frozen check failed with npm exit 1 (code EUSAGE); npm's diagnostic is above" "$FUNCNAME: ${setting}" || return
    grep -qP '^REAL\tnpm\tci\t--dry-run\t.*\t--heading=npm\t--no-color\t--loglevel=error' "${LOG_FILE}" || { fail "$FUNCNAME: ${setting}: the check does not carry its own presentation flags"; return; }
  done
  # the projection too
  lane_prepare "lane-proj-present" kept@1.0.0
  : > "${LOG_FILE}"
  export npm_config_heading=review-npm
  NPM_PROJECTION_FAIL=1 lane_run 'npm install clean@2.0.0'
  unset npm_config_heading
  assert_err_contains_fragment 'npm: code E404' "$FUNCNAME: projection" || return
  grep -qP '^PROJECTION\tnpm\t--package-lock-only\t.*\t--heading=npm\t--no-color\t--loglevel=error\tinstall\tclean@2.0.0$' "${LOG_FILE}" || { fail "$FUNCNAME: the projection does not carry its own presentation flags"; return; }
  # no error line to read: the end of npm's output is shown, and the final line says so; nothing printed is said too
  lane_prepare "lane-ci-nolines" kept@1.0.0
  lane_consistent_graph kept@1.0.0
  : > "${LOG_FILE}"
  NPM_CI_CHECK_ERROR=NOLINES lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: no error line" || return
  assert_err_contains_fragment 'npm output: ' "$FUNCNAME: no error line" || return
  assert_err_contains_fragment 'something else went wrong' "$FUNCNAME: no error line" || return
  assert_err_contains_fragment 'npm printed no error line that could be read, so the end of its output is above' "$FUNCNAME: no error line" || return
  assert_err_not_contains_fragment "npm's diagnostic is above" "$FUNCNAME: no error line" || return
  : > "${LOG_FILE}"
  NPM_CI_CHECK_ERROR=EMPTY lane_run 'npm ci'
  assert_status 1 "$FUNCNAME: empty" || return
  assert_err_contains_fragment 'npm printed nothing' "$FUNCNAME: empty" || return
  assert_err_not_contains_fragment "diagnostic is above" "$FUNCNAME: empty" || return
  # the capability list the selected npm must define carries the three options
  [[ "$(source "${ROOT_DIR}/lib/gate-lib.sh"; type safe_gate_lane_capability | grep -c 'heading color loglevel')" == 1 ]] || { fail "$FUNCNAME: heading, color and loglevel are not in the capability list"; return; }
  pass "$FUNCNAME"
}

# 4. The ci malice line counts the target's distinct identities: evidence missing only for a package the command
# removes does not make the line say the target was partly unread.
case_project_lane_ci_malice_line_counts_the_targets_identities() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-ci-removed" kept@1.0.0 old@1.0.0
  lane_consistent_graph kept@1.0.0 old@1.0.0
  LANE_UNCOMMITTED=1 lane_consistent_graph kept@1.0.0
  : > "${LOG_FILE}"
  SAFE_AUDIT_EVIDENCE_MISSING='["old@1.0.0"]' lane_run 'npm ci'
  assert_status 0 "$FUNCNAME" || return
  assert_err_contains_fragment 'npm ci: 1 entries of the lockfile checked for malice' "$FUNCNAME" || return
  assert_err_not_contains_fragment 'the rest unread' "$FUNCNAME" || return
  assert_err_contains_fragment 'identities read completely' "$FUNCNAME" || return
  pass "$FUNCNAME"
}



# ---- the front door: npm's `--flag=word` of a Boolean-typed flag (ticket 1675) -----------------------------
# nopt reads `--flag=value` as `--flag value`: a Boolean flag leaves a value other than true/false as a
# positional argument, so `npm --json=install blockme` runs `install blockme` and `npm install --json=blockme`
# installs blockme. The gate used to skip every `=` form as one unambiguous word and never audited the package.

assert_front_door_refusal() { # <label> <script>
  local label="$1" script="$2"
  SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
  assert_status 100 "${label}" || return 1
  [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { printf 'stderr:\n%s\n' "$(cat "${ERR_FILE}")" >&2; fail "${label}: not one stderr line"; return 1; }
  assert_err_contains_fragment 'safe: BLOCKED npm — ' "${label}" || return 1
  assert_err_contains_fragment 'to allow: write the option' "${label}" || return 1
  assert_err_contains_fragment 'details: safe explain' "${label}" || return 1
  ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "${label}: npm was delegated to"; return 1; }
  return 0
}

case_npm_front_door_refuses_a_value_npm_leaves_as_an_argument() {
  prepare_case "npm-front-door-refuses"
  local script
  # the seven forms of the ticket: each exited 0 with a delegation and no audit before the front door
  for script in 'npm --json=install -g blockme' 'npm --json=install blockme' 'npm -g=install blockme' 'npm install -g --json=blockme' \
      'npm install --json=blockme' 'npm install -g --force=blockme' 'npm exec --json=blockme'; do
    assert_front_door_refusal "$FUNCNAME: ${script}" "${script}" || return
  done
  # more spellings of the same fact: a negated flag, an abbreviated name, a shorthand cluster, a shorthand,
  # a Boolean-and-String flag with a value npm takes as its own (control below), a String flag whose value npm re-reads as a flag,
  # clusters whose letters leave a word over or hand one option to another (they install a package named warn, info, ...)
  for script in 'npm install --no-json=blockme' 'npm install --no-frobnicate=blockme' 'npm install --jso=blockme' 'npm install -gf=blockme' 'npm install -f=blockme' 'npm install --tag=-g blockme' \
      'npm install -Cq blockme' 'npm install blockme -Cd' 'npm install -Ls blockme' 'npm install -wq blockme' 'npm exec -Cq blockme' 'npm exec --no-package=blockme cowsay' 'npm exec cowsay --no-package=blockme' 'npm install --no-registry=https://r.example/ okpkg' 'npm --json=install exec blockme' 'npm --json=install x blockme' 'npm x --json=blockme' 'npm exec --yes=blockme' 'npm exec -y=blockme'; do
    assert_front_door_refusal "$FUNCNAME: ${script}" "${script}" || return
  done
  pass "$FUNCNAME"
}

# The control: the space form is audited as before, and so is every `=` form whose value the option takes.
case_npm_front_door_leaves_what_npm_reads_as_written() {
  prepare_case "npm-front-door-leaves"
  local script
  SAFE_INSTALL_TEST_SCRIPT='npm --json install -g blockme' run_zsh
  assert_status 104 "$FUNCNAME: space form" || return
  assert_log_contains $'AUDIT\tpackage-audit\tblockme\t--ecosystem\tnpm\t--gate\tinstall\t--op\tinstall' "$FUNCNAME: space form" || return
  for script in 'npm install --registry=https://registry.npmjs.org/ blockme' 'npm install --json=true blockme' 'npm install --json=false blockme' \
      'npm --loglevel=error install blockme' 'npm install --save-prefix=~ blockme' 'npm install --global=true blockme' 'npm install --tag=latest blockme' \
      'npm install --omit=dev blockme' 'npm install --browser=firefox blockme' 'npm install --no-json blockme' 'npm install -gD blockme' 'npm install -gf blockme' 'npm install -qg blockme' 'npm install -dd blockme' 'npm install -DE blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
    grep -q $'^AUDIT\tpackage-audit\tblockme\t--ecosystem\tnpm\t--gate\tinstall\t--op\tinstall' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: blockme was not audited"; return; }
  done
  # an `=` option the gate does not know, on a command it does not gate: both readings give the same command
  SAFE_INSTALL_TEST_SCRIPT='npm view --frobnicate=x kept' run_zsh
  assert_status 0 "$FUNCNAME: unknown option, ungated command" || return
  assert_log_contains $'REAL\tnpm\tview\t--frobnicate=x\tkept' "$FUNCNAME: unknown option, ungated command" || return
  pass "$FUNCNAME"
}

# A name the snapshot does not know: read the command both ways, proceed only when both give the same ungated command.
case_npm_front_door_reads_an_unknown_option_both_ways() {
  prepare_case "npm-front-door-unknown"
  local script
  for script in 'npm install --frobnicate=blockme' 'npm --frobnicate=install blockme' 'npm exec --frobnicate=blockme'; do
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'is not one the gate knows' "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'details: safe explain' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  pass "$FUNCNAME"
}

# With no option in the vector the front door costs nothing and changes nothing; with one it reads the vector as npm does.
case_npm_front_door_is_free_without_an_equals_form() {
  prepare_case "npm-front-door-free"
  local out
  out="$(bash -c 'source "$1/lib/gate-lib.sh"; safe_gate_nopt_load() { echo LOADED; }; safe_gate_npm_front_door install blockme okpkg@1.0.0 -- --json=x; echo "rc=$?"' _ "${ROOT_DIR}" 2>&1)"
  [[ "${out}" == "rc=0" ]] || { fail "$FUNCNAME: the option tables were read or the command was refused (${out})"; return; }
  out="$(bash -c 'source "$1/lib/gate-lib.sh"; safe_gate_nopt_load() { declare -gA SAFE_GATE_NOPT_VARIANT_OPT=() SAFE_GATE_NOPT_VARIANT_SHORT=() SAFE_GATE_NOPT_FLAGS=() SAFE_GATE_NOPT_SHORT=() SAFE_GATE_NOPT_LITS=(); }; safe_gate_nopt_parse() { echo READ; SAFE_GATE_NOPT_LOOSE=(); SAFE_GATE_NOPT_CLUSTER=(); SAFE_GATE_NOPT_NEGATED=(); SAFE_GATE_NOPT_UNSTABLE=(); SAFE_GATE_NOPT_UNKNOWN=(); }; for a in --save-dev -g --Cq -x; do safe_gate_npm_front_door install "$a" blockme; done' _ "${ROOT_DIR}" 2>&1 | tr '\n' ' ')"
  [[ "${out}" == "READ READ READ READ " ]] || { fail "$FUNCNAME: an argument that starts with a dash did not make the front door read the vector (${out})"; return; }
  pass "$FUNCNAME"
}

# The same front door under the audit-only pass of `mise exec -- npm …`, and for npm exec's own spellings.
case_npm_front_door_covers_mise_exec_and_the_exec_switches() {
  prepare_case "npm-front-door-mise-exec"
  local script
  for script in 'mise exec -- npm --json=install blockme' 'mise exec -- npm install --json=blockme' 'mise exec -- npm exec --json=blockme'; do
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'to allow: write the option without the value' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: something was delegated"; return; }
  done
  # npm reads `true`/`false` after a switch as the switch's value: the package is the next word (found by the oracle)
  for script in 'npm exec --yes true blockme' 'npm exec -y false blockme' 'npm exec -p true blockme' 'npm exec --no true blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
    assert_log_contains $'AUDIT\tpackage-audit\tblockme\t--ecosystem\tnpm\t--gate\tinstall\t--op\tinstall' "$FUNCNAME: ${script}" || return
  done
  # --quiet and --silent are shorthands of --loglevel: they take no value, the next word is the package
  SAFE_INSTALL_TEST_SCRIPT='npm exec --quiet true' run_zsh
  assert_status 0 "$FUNCNAME: quiet" || return
  # options npm does not define (pnpm's and bun's) are switches there: the next word is a package
  for script in 'npm install --filter blockme' 'npm install --@scope:registry blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
  done
  pass "$FUNCNAME"
}

case_npm_global_mode_is_read_as_npm_reads_it() {
  prepare_case "npm-global-mode-like-npm"
  # a cluster, a negated shorthand and an option that swallows a following -g
  local script verdicts
  verdicts="$(bash -c 'source "$1/lib/gate-lib.sh"
    for args in "-gf" "-fg" "--local=false" "--local false" "-g --no-global" "--cache -g" "--tag -g" "--registry -g" "--location=global" "-L global" "-g=false" "-g false" "-gD"; do
      safe_gate_npm_global_true install ${args} evilpkg && printf "%s=global\n" "${args}" || printf "%s=local\n" "${args}"
    done' _ "${ROOT_DIR}" 2>&1 | tr '\n' ' ')"
  [[ "${verdicts}" == '-gf=global -fg=global --local=false=global --local false=global -g --no-global=local --cache -g=local --tag -g=global --registry -g=local --location=global=local -L global=local -g=false=local -g false=local -gD=global ' ]] \
    || { fail "$FUNCNAME: ${verdicts}"; return; }
  pass "$FUNCNAME"
}


case_npm_exec_package_then_terminator_fails_closed() {
  prepare_case "npm-exec-package-terminator"
  # npm reads `--package --` as the option with the value true (the terminator is not a value) and fetches the
  # package `true`: the gate does not take the terminator for the package to audit.
  SAFE_INSTALL_TEST_SCRIPT='npm exec --package -- blockme' run_zsh
  assert_status 100 "$FUNCNAME" || return
  assert_err_contains_fragment 'is empty, padded with white space, missing' "$FUNCNAME" || return
  ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: npm was delegated to"; return; }
  pass "$FUNCNAME"
}


# The way out of the unknown-name refusal works, and the advice of the route's refusal is true for npm.
case_npm_front_door_way_out_is_the_environment_for_an_unknown_name() {
  prepare_case "npm-front-door-environment"
  # the refusal names the way out
  SAFE_INSTALL_TEST_SCRIPT='npm install --my-setting=1.2.3 blockme' run_zsh
  assert_status 100 "$FUNCNAME: refusal" || return
  assert_err_contains_fragment 'npm_config_my_setting=<value> npm' "$FUNCNAME: refusal" || return
  # ... and it works: the environment variable does not make the gate refuse or mis-handle the command
  npm_config_my_setting=1.2.3 SAFE_INSTALL_TEST_SCRIPT='npm install -g blockme' run_zsh
  assert_status 104 "$FUNCNAME: audited" || return
  grep -q $'^AUDIT\tpackage-audit\tblockme\t' "${LOG_FILE}" || { fail "$FUNCNAME: blockme was not audited"; return; }
  ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: npm was delegated to"; return; }
  : > "${LOG_FILE}"
  : > "${HOME_DIR}/.stub-log-env"
  npm_config_target=1.2.3 SAFE_INSTALL_TEST_SCRIPT='npm install -g okpkg' run_zsh
  assert_status 0 "$FUNCNAME: a clean package passes" || return
  grep -q $'^AUDIT\tpackage-audit\tokpkg\t' "${LOG_FILE}" || { fail "$FUNCNAME: okpkg was not audited"; return; }
  grep $'^ENVNAMES\t' "${LOG_FILE}" | grep -q 'npm_config_target' || { fail "$FUNCNAME: the variable did not reach npm"; return; }
  # the route's refusal of an unknown space-form flag before the command: the environment for an unknown name ...
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --my-setting install blockme' run_zsh
  assert_status 100 "$FUNCNAME: unknown flag" || return
  assert_err_contains_fragment 'npm_config_my_setting=<value> npm' "$FUNCNAME: unknown flag" || return
  assert_err_not_contains_fragment "rewrite it as" "$FUNCNAME: unknown flag" || return
  # a name npm defines is read by the gate as npm reads it, in the space form or the `=` form
  SAFE_INSTALL_TEST_SCRIPT='npm --fetch-retries 3 install blockme' run_zsh
  assert_status 104 "$FUNCNAME: known flag, space form" || return
  SAFE_INSTALL_TEST_SCRIPT='npm --fetch-retries=3 install blockme' run_zsh
  assert_status 104 "$FUNCNAME: known flag, = form" || return
  # an abbreviation is not a name the gate knows: the way out is the full name
  SAFE_INSTALL_TEST_SCRIPT='npm --fetch-retri 3 install blockme' run_zsh
  assert_status 100 "$FUNCNAME: abbreviated flag" || return
  assert_err_contains_fragment 'write the full option name npm defines' "$FUNCNAME: abbreviated flag" || return
  SAFE_INSTALL_TEST_SCRIPT='npm --fetch-retries 3 install blockme' run_zsh
  assert_status 104 "$FUNCNAME: full name" || return
  # the other tools' text is as it was
  SAFE_INSTALL_TEST_SCRIPT='pip --my-setting install blockme' run_zsh
  assert_err_contains_fragment "rewrite it as '--my-setting=<value>'" "$FUNCNAME: pip" || return
  pass "$FUNCNAME"
}


# Everyday npm command lines read exactly as before the front door: the same status, the same audited packages and the
# same delegation through the gate of the base branch (SAFE_TEST_BASE_REF, default origin/main) and through this one.
# The gate's effects are stubbed the way the option oracle stubs them (tests/lib/npm-option-gate-oracle.sh).
case_npm_everyday_commands_are_unchanged_by_the_front_door() {
  prepare_case "npm-everyday-unchanged"
  # The lines and their outcomes are RECORDED (tests/fixtures/npm-everyday.{lines,expected}): the outcome of each line is
  # what the gate did with it before the front door existed, apart from the one difference documented below. The
  # recording does not depend on any git ref, so it holds after the change is merged.
  local lines="${ROOT_DIR}/tests/fixtures/npm-everyday.lines" expected="${ROOT_DIR}/tests/fixtures/npm-everyday.expected"
  local runner="${CASE_DIR}/everyday-runner.sh" project="${CASE_DIR}/everyday-project" new_out="${CASE_DIR}/everyday-new.out" count
  mkdir -p "${project}" "${CASE_DIR}/everyday-home-b"
  printf '{"name":"everyday","version":"1.0.0"}\n' > "${project}/package.json"
  cat > "${runner}" <<'RUNNER'
#!/usr/bin/env bash
# $1 the gate library, stdin the command lines
lib="$1"
cd "$2" || exit 1
export HOME="$3"
# shellcheck source=/dev/null
source "${lib}" >/dev/null 2>&1 || exit 99
REC="$3/record"
safe_gate_exec_real() { printf 'DELEGATE %s\n' "$*" >> "${REC}"; exit 0; }
safe_gate_check() { printf 'AUDIT %s\n' "$1" >> "${REC}"; return 0; }
safe_gate_check_many() { shift; local p; for p in "$@"; do printf 'AUDIT %s\n' "${p}" >> "${REC}"; done; return 0; }
safe_gate_scan_project() { printf 'SCAN\n' >> "${REC}"; return 0; }
safe_gate_private_npm_project() { return 0; }
safe_gate_project_lane_enabled() { return 1; }
safe_gate_npm_scripts_env() { return 0; }
safe_gate_err() { printf 'ERR %s\n' "$*" >> "${REC}"; }
while IFS= read -r line; do
  : > "${REC}"
  eval "set -- ${line}"
  ( safe_gate_npm_like npm "$@" ) >/dev/null 2>&1
  printf '%s => rc=%s | %s\n' "${line}" "$?" "$(tr '\n' ';' < "${REC}")"
done
RUNNER
  bash "${runner}" "${ROOT_DIR}/lib/gate-lib.sh" "${project}" "${CASE_DIR}/everyday-home-b" < "${lines}" > "${new_out}" 2>&1
  count="$(wc -l < "${lines}")"
  (( count >= 30 )) || { fail "$FUNCNAME: only ${count} lines"; return; }
  [[ "$(wc -l < "${new_out}")" == "${count}" ]] || { fail "$FUNCNAME: the gate did not read every line ($(head -n 3 "${new_out}"))"; return; }
  if ! diff -u "${expected}" "${new_out}" >&2; then
    fail "$FUNCNAME: a line has another outcome than the recorded one"
    return
  fi
  printf '# %s: %s command lines, the recorded outcomes\n' "$FUNCNAME" "${count}"
  # The one difference this change makes to an everyday line: a shorthand cluster that contains -g is a global install
  # for npm (nopt expands -gD to --global --save-dev), and so for the gate (it used to take it for a project install,
  # with the project scan).
  printf 'install -gD okpkg\n' > "${CASE_DIR}/everyday-cluster.lines"
  bash "${runner}" "${ROOT_DIR}/lib/gate-lib.sh" "${project}" "${CASE_DIR}/everyday-home-b" < "${CASE_DIR}/everyday-cluster.lines" > "${new_out}" 2>&1
  grep -q 'rc=0 | AUDIT okpkg;DELEGATE npm install -gD okpkg;' "${new_out}" \
    || { cat "${new_out}" >&2; fail "$FUNCNAME: -gD is not read as a global install"; return; }
  # optional: against another gate library (SAFE_TEST_BASE_REF names a git ref), the same lines read the same
  if [[ -n "${SAFE_TEST_BASE_REF:-}" ]] && git -C "${ROOT_DIR}" show "${SAFE_TEST_BASE_REF}:lib/gate-lib.sh" > "${CASE_DIR}/base-gate-lib.sh" 2>/dev/null; then
    mkdir -p "${CASE_DIR}/everyday-home-a"
    bash "${runner}" "${CASE_DIR}/base-gate-lib.sh" "${project}" "${CASE_DIR}/everyday-home-a" < "${lines}" > "${CASE_DIR}/everyday-base.out" 2>&1
    diff -u "${CASE_DIR}/everyday-base.out" "${expected}" >&2 || { fail "$FUNCNAME: the recorded outcomes differ from ${SAFE_TEST_BASE_REF}'s"; return; }
  fi
  pass "$FUNCNAME"
}


# The arguments the gate's extractors and npm read differently are refused (no value printed, one line, a way out).
case_npm_argument_hygiene_refuses_what_extractors_and_npm_read_differently() {
  prepare_case "npm-argument-hygiene"
  local script
  for script in "npm install \$'blockme\nokpkg'" "npm install \$'blockme\r'" "npm install ' blockme'" "npm install 'blockme '" "npm install -- ' blockme'" 'npm install -' \
      'npm install blockme -' "npm exec \$'cowsay\n'" "npm exec ' cowsay'"; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: ${script}: not one line"; return; }
    assert_err_contains_fragment 'to allow:' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  # the way out works: one clean package per argument
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm install blockme okpkg' run_zsh
  assert_status 104 "$FUNCNAME: the way out" || return
  # arguments after the exec terminator are the command's own, and an operand with inner white space is fine
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT="npm exec cowsay -- ' padded ' x" run_zsh
  assert_status 0 "$FUNCNAME: after the terminator" || return
  pass "$FUNCNAME"
}

# What the differential oracle found in round 2: the command and the packages are npm's reading, not a short list's.
case_npm_reading_decides_command_and_packages_found_by_the_oracle() {
  prepare_case "npm-reading-decides"
  local script
  # a negated option takes a listed literal as its value (nopt's Boolean branch): the command is `install`, not `always`
  for script in 'npm --no-color always install blockme' 'npm install --package --prefix blockme' 'npm install --package --registry blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
    grep -q $'^AUDIT\tpackage-audit\tblockme\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: blockme was not audited"; return; }
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  # `--no-location global` is the location global, which the gate never takes for global mode (npm 8.1.0 does not act on it)
  printf '{"name":"scan-decision","version":"1.0.0"}\n' > "${WORK_DIR}/package.json"
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --no-location global install blockme' run_zsh
  assert_status 100 "$FUNCNAME: --no-location global" || return
  ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: --no-location global: npm was delegated to"; return; }
  # an option terminator before the command makes every later option an argument: refused, with a way out that works
  for script in 'npm -- x -c cmd' 'npm --cache -- x -c cmd' 'npm -- install -D blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'terminator is written before the command' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm install -D blockme' run_zsh
  assert_status 104 "$FUNCNAME: the way out" || return
  pass "$FUNCNAME"
}

# An option only some npm versions define is read every way the versions read it (the snapshot is a union over npm 8.1 to
# 12.2, and an older npm takes the word after `--allow-git` for a package, a newer one for the option's value).
case_npm_version_dependent_options_are_read_every_way() {
  prepare_case "npm-version-dependent-options"
  local script
  # each must refuse, or audit blockme: here they refuse (the readings give different packages)
  for script in 'npm install --allow-git blockme' 'npm install --min-release-age blockme' 'npm install --cpu blockme' 'npm install -g --allow-git blockme' \
      'npm install --install-strategy blockme' 'npm install --install-strategy nested blockme' 'npm --cpu x64 install blockme' 'npm exec --cpu blockme' \
      'npm install --logs-dir /x blockme' 'npm prune --os aix'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: ${script}: not one line"; return; }
    assert_err_contains_fragment 'read differently by the npm versions the gate vouches for' "$FUNCNAME: ${script}" || return
    assert_err_not_contains_fragment 'blockme' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  # an abbreviation of such a name: an option's name to one npm, an unknown name to another
  for script in 'npm install --allow-d blockme' 'npm install --allow- blockme' 'npm install --min-rel blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'is an abbreviation that the npm versions the gate vouches for read differently' "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'write the full option name' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  # the way out printed: the value attached. Every version consumes an = value for a name it does not define as Boolean,
  # and the audit sees the package
  for script in 'npm install --install-strategy=nested blockme' 'npm install --cpu=x64 blockme' 'npm install --allow-git=none blockme' 'npm install -g --min-release-age=7 blockme' \
      'npm install --loglevel=info blockme' 'npm install --no-install-links blockme' 'npm install --init-private blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
    grep -q $'^AUDIT\tpackage-audit\tblockme\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: blockme was not audited"; return; }
  done
  # a command the gate does not audit under any reading goes on
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm run build --cpu x64' run_zsh
  assert_status 0 "$FUNCNAME: ungated" || return
  # up to four such options are read in every combination; five refuse, agreement or not
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm install --cpu=x64 --os=linux --libc=glibc --allow-git=none --min-release-age=1 blockme' run_zsh
  assert_status 100 "$FUNCNAME: five" || return
  assert_err_contains_fragment 'too many to read every way' "$FUNCNAME: five" || return
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm install --cpu=x64 --os=linux --libc=glibc --allow-git=none blockme' run_zsh
  assert_status 104 "$FUNCNAME: four" || return
  pass "$FUNCNAME"
}

# Third round (ticket 1675, review 2): the location never decides global mode for the gate; a negated value option followed
# by a word; the printed ways out; the child's arguments after the exec terminator.
case_npm_location_global_is_refused_and_g_is_the_way_out() {
  prepare_case "npm-location-global"
  local script
  printf '{"name":"scan-decision","version":"1.0.0"}\n' > "${WORK_DIR}/package.json"
  # npm 8.1.0 parses `--location global` and does not act on it (its `prefix` is the project's there, the installation's
  # on every later npm): in every spelling, on a gated command, the gate refuses
  for script in 'npm install --location global blockme' 'npm install --location=global blockme' 'npm --location global install blockme' 'npm -L global install blockme' \
      'npm install -L=global blockme' 'npm install --locat global blockme' 'npm install --no-location global blockme' 'npm exec --location global cowsay' \
      'npm install blockme --location=global' 'npm ci --location=global' 'npm update --location=global' 'npm dedupe --location=global'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: ${script}: not one line"; return; }
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
    ! grep -q 'repo-audit' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: the project scan ran under a global reading"; return; }
  done
  assert_err_contains_fragment 'use -g (or --global)' "$FUNCNAME: the way out is printed" || return
  # the way out: -g, global, no project scan, the package audited
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm install -g blockme' run_zsh
  assert_status 104 "$FUNCNAME: -g" || return
  grep -q $'^AUDIT\tpackage-audit\tblockme\t' "${LOG_FILE}" || { fail "$FUNCNAME: -g: blockme was not audited"; return; }
  ! grep -q 'repo-audit' "${LOG_FILE}" || { fail "$FUNCNAME: -g ran the project scan"; return; }
  # another location does not change the mode: the project scan runs, both directions of the scan decision
  for script in 'npm install --location project blockme' 'npm install --location=user blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: ${script}" || return
    grep -q 'repo-audit' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: no project scan"; return; }
  done
  # a command the gate does not audit is not refused
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --location global prefix' run_zsh
  assert_status 0 "$FUNCNAME: prefix" || return
  pass "$FUNCNAME"
}

case_npm_negated_value_option_followed_by_a_word_refuses() {
  prepare_case "npm-negated-value-option"
  local script
  # `--no-local-address 127.0.0.1`: every reference gives the address to the option, the gate used to audit it as a package
  # (the literals of local-address are the machine's interfaces: no list of them is shipped)
  for script in 'npm install --no-local-address 127.0.0.1 blockme' 'npm install --no-local-address blockme' \
      'npm install --no-registry blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: ${script}: not one line"; return; }
    assert_err_contains_fragment 'negates an option that takes a value and is followed by a word' "$FUNCNAME: ${script}" || return
    assert_err_not_contains_fragment '127.0.0.1' "$FUNCNAME: ${script}" || return
    ! grep -q $'^AUDIT\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: something was audited (an address, a literal)"; return; }
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  # the printed ways out, followed literally: the word before the negated option; the plain option with its value attached
  for script in 'npm install blockme --no-local-address' 'npm install blockme --no-color' 'npm install --local-address=127.0.0.1 blockme' 'npm install --color=always blockme' \
      'npm install --no-color blockme' 'npm install --no-color always blockme' 'npm install --no-save blockme'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 104 "$FUNCNAME: way out: ${script}" || return
    grep -q $'^AUDIT\tpackage-audit\tblockme\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: blockme was not audited"; return; }
    [[ "$(grep -c $'^AUDIT\t' "${LOG_FILE}")" == 1 ]] || { fail "$FUNCNAME: ${script}: more than blockme was audited"; return; }
  done
  pass "$FUNCNAME"
}

case_npm_exec_and_abbreviation_refusals_print_no_value_and_a_way_out_that_works() {
  prepare_case "npm-refusal-ways-out"
  # an attached call string: no value printed, the way out works (a call string alone names no package)
  SAFE_INSTALL_TEST_SCRIPT='npm exec -c=PUBLIC_FIXTURE' run_zsh
  assert_status 100 "$FUNCNAME: -c=" || return
  [[ "$(wc -l < "${ERR_FILE}")" -eq 1 ]] || { fail "$FUNCNAME: -c=: not one line"; return; }
  assert_err_not_contains_fragment 'PUBLIC_FIXTURE' "$FUNCNAME: -c=" || return
  assert_err_contains_fragment "write the call as '-c <call>' or '--call=<call>'" "$FUNCNAME: -c=" || return
  local script
  for script in 'npm exec -c pwd' 'npm exec --call=pwd'; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 0 "$FUNCNAME: way out: ${script}" || return
    grep -q $'^REAL\tnpm\texec' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was not run"; return; }
  done
  # an abbreviation: the printed way out names no abbreviation as the full name
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --edi=vi prefix' run_zsh
  assert_status 100 "$FUNCNAME: --edi=" || return
  assert_err_not_contains_fragment 'edi=<value>' "$FUNCNAME: --edi=" || return
  assert_err_contains_fragment "the option's full name" "$FUNCNAME: --edi=" || return
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --editor=vi prefix' run_zsh
  assert_status 0 "$FUNCNAME: --editor=" || return
  # when exactly one option begins with the text, the full name is named
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT='npm --sav=x install blockme' run_zsh
  assert_status 100 "$FUNCNAME: --sav=" || return
  pass "$FUNCNAME"
}

case_npm_exec_terminator_leaves_the_childs_arguments_alone() {
  prepare_case "npm-exec-terminator-child"
  # the child's own arguments after the terminator are not read: a line break there is JavaScript, not a package
  SAFE_INSTALL_TEST_SCRIPT="npm exec -- node -e \$'let x = 1\nvoid x'" run_zsh
  assert_status 0 "$FUNCNAME: exec -- node -e <two lines>" || return
  grep -q $'^REAL\tnpm\texec' "${LOG_FILE}" || { fail "$FUNCNAME: npm was not run"; return; }
  : > "${LOG_FILE}"
  SAFE_INSTALL_TEST_SCRIPT="npm exec cowsay -- node -e \$'let x = 1\nvoid x'" run_zsh
  assert_status 0 "$FUNCNAME: exec cowsay -- <two lines>" || return
  # a line break in an argument a gate extractor reads still refuses
  for script in "npm install \$'blockme\nx'" "npm exec \$'cowsay\nx'" "npm exec -- \$'cowsay\nx'" "npm exec \$'--package=blockme\nx' cowsay" "npm install -- \$'blockme\nx'"; do
    : > "${LOG_FILE}"
    SAFE_INSTALL_TEST_SCRIPT="${script}" run_zsh
    assert_status 100 "$FUNCNAME: ${script}" || return
    assert_err_contains_fragment 'holds a line break' "$FUNCNAME: ${script}" || return
    ! grep -q $'^REAL\t' "${LOG_FILE}" || { fail "$FUNCNAME: ${script}: npm was delegated to"; return; }
  done
  pass "$FUNCNAME"
}

# ---- the cooldown of the project lane (ticket 1635) ---------------------------------------------------------
# A registry and an advisory service of the case's own (tests/lib/fake_registry.py): the lane's publish-time reading
# reaches them through the test's safe-core wrapper (LANE_RELEASES_BASE), never a real registry.
COOLDOWN_REG_PID=""
cooldown_registry_stop() {
  [[ -z "${COOLDOWN_REG_PID}" ]] || { kill "${COOLDOWN_REG_PID}" 2>/dev/null; wait "${COOLDOWN_REG_PID}" 2>/dev/null; }
  COOLDOWN_REG_PID=""
  unset LANE_RELEASES_BASE
}
# $1 the case's directory, then words, one full metadata document per name (the name, the version's time or none,
# the versions listed, the last-modified time):
#   name@version=<hours ago>       the version is listed with that publish time
#   name@version=none              the version is listed WITHOUT a time of its own
#   name:modified=<hours ago>      the document's last-modified time (default: now)
cooldown_registry_start() {
  local dir="$1" word name version hours at
  shift
  cooldown_registry_stop
  mkdir -p "${dir}/reg/packuments"
  : > "${dir}/reg/log"
  for word in "$@"; do
    local file stamp
    if [[ "${word}" == *:modified=* ]]; then
      name="${word%%:*}"; hours="${word#*=}"
      file="${dir}/reg/packuments/${name}.json"
      [[ -f "${file}" ]] || printf '{"name":"%s","time":{},"versions":{}}\n' "${name}" > "${file}"
      stamp="$(date -u -d "${hours} hours ago" +%Y-%m-%dT%H:%M:%S.000Z)"
      jq -c --arg t "${stamp}" '.time.modified = $t' "${file}" > "${file}.new" && mv "${file}.new" "${file}"
      continue
    fi
    name="${word%%@*}"; version="${word#*@}"; hours="${version#*=}"; version="${version%%=*}"
    file="${dir}/reg/packuments/${name}.json"
    [[ -f "${file}" ]] || printf '{"name":"%s","time":{"modified":"%s"},"versions":{}}\n' "${name}" "$(date -u +%Y-%m-%dT%H:%M:%S.000Z)" > "${file}"
    if [[ "${hours}" == none ]]; then
      jq -c --arg v "${version}" '.versions[$v] = {}' "${file}" > "${file}.new" && mv "${file}.new" "${file}"
    else
      stamp="$(date -u -d "${hours} hours ago" +%Y-%m-%dT%H:%M:%S.000Z)"
      jq -c --arg v "${version}" --arg t "${stamp}" '.time[$v] = $t | .versions[$v] = {}' "${file}" > "${file}.new" && mv "${file}.new" "${file}"
    fi
  done
  rm -f "${dir}/reg/port"
  python3 "${ROOT_DIR}/tests/lib/fake_registry.py" "${dir}/reg" "${dir}/reg/port" "${dir}/reg/log" >/dev/null 2>&1 &
  COOLDOWN_REG_PID=$!
  for at in $(seq 1 50); do [[ -s "${dir}/reg/port" ]] && break; sleep 0.1; done
  export LANE_RELEASES_BASE="http://127.0.0.1:$(cat "${dir}/reg/port")"
}
cooldown_config() { # <days> [mode]
  printf '{"install":{"project_lane":true,"cooldown_days":%s%s}}\n' "$1" "${2:+,\"cooldown_security_fix\":\"$2\"}" > "${HOME_DIR}/.config/safe/run/config.json"
}

# The selection aid: npm's release-age filter on every npm command line of the lane, at install.cooldown_days; a version
# named exactly is excluded by name, a range is not; nothing is left for a configuration file to widen. The options are
# the lane's own invocations of the real npm: no caller's front door reads them.
case_project_lane_cooldown_sets_npms_release_age_filter_on_every_run() {
  skip_lockdiff_case "$FUNCNAME" || return
  local line n
  # default: 3 days, no exclusion (the list is set EMPTY, so that no outside source can exclude a package)
  lane_prepare "lane-cooldown-flags" kept@1.0.0
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run 'npm update'
  assert_status 0 "$FUNCNAME: range" || return
  n=0
  while IFS= read -r line; do
    n=$((n + 1))
    [[ "${line}" == *$'\t--min-release-age=3\t--min-release-age-exclude='* && "${line}" != *"--min-release-age-exclude=c"* ]] || { fail "$FUNCNAME: a run without the window or with an exclusion: ${line}"; return; }
  done < <(grep -P '^(REAL|PROJECTION)\tnpm\t' "${LOG_FILE}" | grep -vP '^REAL\tnpm\t(--version|config\tget)')
  (( n >= 3 )) || { fail "$FUNCNAME: only ${n} npm runs carried the filter"; return; }
  # the operator's window, and an exact name: excluded by name; two names: both
  lane_prepare "lane-cooldown-named" kept@1.0.0
  cooldown_config 7
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run 'npm install clean@2.0.0'
  assert_status 0 "$FUNCNAME: exact" || return
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age=7\t--min-release-age-exclude=clean\t--heading=npm' "${LOG_FILE}" || { fail "$FUNCNAME: the exact version is not excluded by name in a 7-day window"; return; }
  # days 0 still sets the window (to cancel any other source's)
  lane_prepare "lane-cooldown-off" kept@1.0.0
  cooldown_config 0
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run 'npm update'
  assert_status 0 "$FUNCNAME: off" || return
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age=0\t' "${LOG_FILE}" || { fail "$FUNCNAME: a disabled cooldown does not cancel other sources' window"; return; }
  assert_err_contains_fragment 'cooldown: off' "$FUNCNAME: off" || return
  # an install.cooldown_days that is not an integer reads as today's gate reads it: 3
  lane_prepare "lane-cooldown-bad-days" kept@1.0.0
  printf '{"install":{"project_lane":true,"cooldown_days":"soon"}}\n' > "${HOME_DIR}/.config/safe/run/config.json"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" NPM_PROJECTION_MANIFEST_JSON="${LANE_CLEAN_ADD_MANIFEST}" lane_run 'npm update'
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age=3\t' "${LOG_FILE}" || { fail "$FUNCNAME: a bad cooldown_days is not 3"; return; }
  # the lane's own npm runs are not the caller's command line: its internal runs never call the front door
  ! grep -nE 'safe_gate_npm_front_door|safe_gate_npm_like' < <(sed -n '/^safe_gate_lane_npm_in()/,/^}/p;/^safe_gate_project_lane_run()/,/^safe_gate_project_lane_frozen_check()/p' "${ROOT_DIR}/lib/gate-lib.sh") >/dev/null \
    || { fail "$FUNCNAME: the lane's own runs reach the front door"; return; }
  pass "$FUNCNAME"
}

# No configuration file or environment variable can widen the cooldown: the settings are read back from npm's own
# effective configuration, which must hold exactly the window and the exclusions the lane set, and no `before`.
case_project_lane_cooldown_cannot_be_widened_by_configuration() {
  skip_lockdiff_case "$FUNCNAME" || return
  local cfg
  # a project .npmrc that sets the window, the exclusions or a date is not on the lane's allow-list: the command goes to
  # today's gate on the one-shot route (which has its own cooldown), and the lane's projection never runs
  for cfg in 'before=2030-01-01' 'min-release-age=0' 'min-release-age-exclude[]=evil'; do
    lane_prepare "lane-cooldown-rc-${RANDOM}" kept@1.0.0
    printf '%s\n' "${cfg}" > "${WORK_DIR}/.npmrc"
    lane_commit
    lane_run 'npm update'
    assert_err_contains_fragment 'one-shot' "$FUNCNAME: .npmrc ${cfg}" || return
    assert_err_contains_fragment 'is not on the allow-list' "$FUNCNAME: .npmrc ${cfg}" || return
    assert_log_not_contains_fragment $'PROJECTION\tnpm' "$FUNCNAME: .npmrc ${cfg}" || return
  done
  # an absolute date in the environment or in the operator's own npmrc competes with the window: refused, naming the setting
  lane_prepare "lane-cooldown-before-env" kept@1.0.0
  npm_config_before=2030-01-01 lane_run 'npm update'
  lane_unsupported_case "$FUNCNAME: env before" update 'a before date' || return
  assert_err_contains_fragment 'a before date' "$FUNCNAME: env before" || return
  # `before` must be absent or null: false is not absent
  lane_prepare "lane-cooldown-before-false" kept@1.0.0
  npm_config_before=false lane_run 'npm update'
  lane_unsupported_case "$FUNCNAME: before=false" update 'a before date' || return
  assert_err_contains_fragment 'a before date' "$FUNCNAME: before=false" || return
  lane_prepare "lane-cooldown-before-user" kept@1.0.0
  printf 'before=2030-01-01\n' > "${HOME_DIR}/.npmrc"
  lane_run 'npm update'
  lane_unsupported_case "$FUNCNAME: user before" update 'a before date' || return
  assert_err_contains_fragment 'a before date' "$FUNCNAME: user before" || return
  rm -f "${HOME_DIR}/.npmrc"
  # what npm reports instead of the lane's settings is read back, positively and typed. Each effective configuration is
  # built with jq and each case asserts ITS OWN diagnostic (not any non-zero exit), for both probes
  local base='{"package-lock":true,"ignore-scripts":true}' probe config fragment
  for probe in effective frozen; do
    while IFS='|' read -r fragment config; do
      lane_prepare "lane-cooldown-${probe}-${RANDOM}" kept@1.0.0
      : > "${LOG_FILE}"
      config="$(jq -c "${config}" <<<"${base}")"
      if [[ "${probe}" == effective ]]; then NPM_LOCKDIFF_EFFECTIVE_CONFIG_JSON="${config}" lane_run 'npm update'
      else NPM_FROZEN_CONFIG_JSON="${config}" lane_run 'npm update'; fi
      lane_unsupported_case "$FUNCNAME: ${probe}: ${fragment}" update "${fragment}" || return
      assert_err_contains_fragment "${fragment}" "$FUNCNAME: ${probe}: ${fragment}" || return
      assert_log_not_contains_fragment $'PROJECTION\tnpm' "$FUNCNAME: ${probe}: ${fragment}" || return
    done <<'CONFIGS'
min-release-age 0 where the cooldown sets 3|. + {"min-release-age": 0}
min-release-age of type string where the cooldown sets 3|. + {"min-release-age": "3"}
min-release-age 30 where the cooldown sets 3|. + {"min-release-age": 30}
min-release-age-exclude that is not a list of names|. + {"min-release-age-exclude": "evil"}
min-release-age-exclude that is not a list of names|. + {"min-release-age-exclude": null}
min-release-age-exclude that is not a list of names|. + {"min-release-age-exclude": [1]}
min-release-age-exclude that is not the list of the exact versions the command names|. + {"min-release-age-exclude": ["evil"]}
a before date|. + {"before": "2030-01-01T00:00:00.000Z"}
a before date|. + {"before": false}
a before date|. + {"before": 0}
CONFIGS
  done
  # a field that is ABSENT is a refusal too (an absent exclusion field is not the empty list), and so is a configuration
  # that is not an object
  for config in '{"package-lock":true,"ignore-scripts":true,"min-release-age":3}|min-release-age-exclude absent' \
      '{"package-lock":true,"ignore-scripts":true,"min-release-age-exclude":[""]}|min-release-age absent' '[1]|an effective configuration that is not an object'; do
    lane_prepare "lane-cooldown-absent-${RANDOM}" kept@1.0.0
    NPM_CONFIG_LIST_RAW="${config%%|*}" lane_run 'npm update'
    [[ "${STATUS}" -ne 0 ]] || { fail "$FUNCNAME: ${config} was accepted"; return; }
    assert_lane_no_delegate "$FUNCNAME: ${config}" || return
    assert_log_not_contains_fragment $'PROJECTION\tnpm' "$FUNCNAME: ${config}" || return
  done
  lane_prepare "lane-cooldown-absent-diagnostic" kept@1.0.0
  NPM_CONFIG_LIST_RAW='{"package-lock":true,"ignore-scripts":true,"min-release-age":3}' lane_run 'npm update'
  assert_err_contains_fragment 'min-release-age-exclude absent' "$FUNCNAME: absent exclusion" || return
  # exclusions and a zero window in the operator's own npmrc cannot widen it: the command line outranks them, and the
  # exclusion list npm reports is the lane's own
  lane_prepare "lane-cooldown-user-exclusions" kept@1.0.0
  printf 'min-release-age=0\nmin-release-age-exclude[]=evil\n' > "${HOME_DIR}/.npmrc"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm update'
  assert_status 0 "$FUNCNAME: user exclusions outranked" || return
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age=3\t--min-release-age-exclude=\t' "${LOG_FILE}" || { fail "$FUNCNAME: the lane's window and empty exclusion list are not on the command line"; return; }
  pass "$FUNCNAME"
}

# A version the caller names, published yesterday: refused 100 with the date it becomes installable; nothing is written.
case_project_lane_cooldown_named_young_version_waits_with_the_date() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-cooldown-named-young" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=20" "kept@1.0.0=2400"
  local before want
  before="$(lane_digests)"
  want="$(date -u -d "20 hours ago + 3 days" +%Y-%m-%dT%H:%M)"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME" || return
  assert_lane_final_line install "$FUNCNAME" || return
  assert_err_contains_fragment 'fresh@2.0.0 was published ' "$FUNCNAME" || return
  assert_err_contains_fragment 'is inside the 3-day cooldown; it becomes installable on '"${want:0:13}" "$FUNCNAME" || return
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age-exclude=fresh\t' "${LOG_FILE}" || { fail "$FUNCNAME: the named version is not excluded from npm's filter by name"; return; }
  [[ "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: the project changed"; return; }
  assert_log_not_contains_fragment $'REAL\tnpm\tci\t--ignore-scripts' "$FUNCNAME" || return
  assert_lane_no_leftover "$FUNCNAME" || return
  # the same command with an old version passes, and the report says what was judged
  lane_prepare "lane-cooldown-named-old" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=2400"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  cooldown_registry_stop
  assert_status 0 "$FUNCNAME: an old version" || return
  assert_err_contains_fragment 'cooldown: 1 introduced version(s) judged against the 3-day window' "$FUNCNAME: old" || return
  pass "$FUNCNAME"
}

# npm's filter keeps young versions out of an update; safe's own reading is the decision: the report lists nothing young,
# and what is already in the baseline is not judged (the coordinator's default for the spec's first open question).
case_project_lane_cooldown_judges_what_the_command_introduces_not_the_baseline() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-cooldown-update" kept@1.0.0 old@1.0.0
  cooldown_registry_start "${CASE_DIR}" "kept@1.0.0=20" "old@1.0.0=20" "old@1.1.0=2400"
  # the baseline holds two entries published 20 hours ago: neither is judged; the update introduces an old version
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 old@1.1.0)" lane_run 'npm update'
  cooldown_registry_stop
  assert_status 0 "$FUNCNAME" || return
  assert_err_contains_fragment 'cooldown: 1 introduced version(s) judged against the 3-day window' "$FUNCNAME" || return
  grep -qP '^PROJECTION\tnpm\t.*\t--min-release-age=3\t--min-release-age-exclude=\t' "${LOG_FILE}" || { fail "$FUNCNAME: the update's projection has no window"; return; }
  ! grep -q 'GET /kept' "${CASE_DIR}/reg/log" || { fail "$FUNCNAME: a baseline entry's publish time was asked"; return; }
  pass "$FUNCNAME"
}

# Another young version of an excluded name, and a young entry a lockfile on disk carries that is not the baseline,
# are caught by safe's own reading (npm's filter cannot see either).
case_project_lane_cooldown_catches_another_young_version_and_a_young_entry_on_disk() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-cooldown-same-name" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=2400" "fresh@2.1.0=10" "kept@1.0.0=2400"
  local target
  target="$(lane_lock kept@1.0.0 fresh@2.0.0 | jq -c '.packages["node_modules/kept/node_modules/fresh"] = .packages["node_modules/fresh"] + {version: "2.1.0", resolved: "https://registry.npmjs.org/fresh/-/fresh-2.1.0.tgz"}')"
  NPM_LOCK_MUTATION_JSON="${target}" lane_run 'npm install fresh@2.0.0'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME: same name" || return
  assert_lane_final_line install "$FUNCNAME: same name" || return
  assert_err_contains_fragment 'fresh@2.1.0 was published ' "$FUNCNAME: same name" || return
  assert_err_not_contains_fragment 'fresh@2.0.0 was published' "$FUNCNAME: same name" || return
  # a lockfile on disk that adds a young entry the baseline (the committed lockfile) does not hold
  lane_prepare "lane-cooldown-disk" kept@1.0.0
  lane_lock kept@1.0.0 young@1.0.0 > "${WORK_DIR}/package-lock.json"
  cooldown_registry_start "${CASE_DIR}" "young@1.0.0=10" "kept@1.0.0=2400"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 young@1.0.0)" lane_run 'npm update'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME: disk" || return
  assert_lane_final_line update "$FUNCNAME: disk" || return
  assert_err_contains_fragment 'young@1.0.0 was published ' "$FUNCNAME: disk" || return
  pass "$FUNCNAME"
}

# A registry answer without a publish time is disclosed in the report and does not stop; a reading is cached per version.
# There is no gap that lets a version pass unread. A version the document lists without a time of its own is judged by
# the document's last-modified time, which no publish time in it can exceed: old enough when that is older than the
# cooldown, otherwise it waits until the bound is.
case_project_lane_cooldown_a_version_without_its_own_time_is_judged_by_the_last_modified_time() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-cooldown-bounded-old" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=none" "fresh:modified=2400" "kept@1.0.0=2400"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
  cooldown_registry_stop
  assert_status 0 "$FUNCNAME: old bound" || return
  assert_err_contains_fragment 'cooldown: 1 introduced version(s) judged' "$FUNCNAME: old bound" || return
  lane_prepare "lane-cooldown-bounded-young" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=none" "fresh:modified=10" "kept@1.0.0=2400"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME: young bound" || return
  assert_err_contains_fragment 'fresh@2.0.0 has no publish time of its own in the registry' "$FUNCNAME: young bound" || return
  assert_err_contains_fragment 'so it may be inside the 3-day cooldown; it is certainly old enough on ' "$FUNCNAME: young bound" || return
  pass "$FUNCNAME"
}

# Everything else that leaves a version without a time is MISSING EVIDENCE: 102, naming how many readings are missing, never
# a pass. An answer for another package, a redirect, an error status, an unreadable answer and an unreachable registry.
case_project_lane_cooldown_every_other_failure_is_missing_evidence() {
  skip_lockdiff_case "$FUNCNAME" || return
  local cause want
  # name|how the registry misbehaves|the cause the report names
  while IFS='|' read -r cause want; do
    lane_prepare "lane-cooldown-fail-${RANDOM}" kept@1.0.0
    cooldown_registry_start "${CASE_DIR}" "kept@1.0.0=2400"
    case "${cause}" in
      status) printf '503\n' > "${CASE_DIR}/reg/packuments/fresh.status" ;;
      redirect) printf 'http://127.0.0.1:1/fresh\n' > "${CASE_DIR}/reg/packuments/fresh.redirect" ;;
      wrong-package) printf '{"name":"someone-else","time":{"2.0.0":"2000-01-01T00:00:00.000Z","modified":"2026-01-01T00:00:00.000Z"},"versions":{"2.0.0":{}}}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      garbled) printf '{"name":"fresh","time":{' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      truncated) printf '{"name":"fresh","time":{"2.0.0":"2000-01-01T00:00:00.000Z","modified":"2026-01-01T00:00:00.000Z"},"versions":{"2.0.0":{}' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      trailing) printf '{"name":"fresh","time":{"2.0.0":"2000-01-01T00:00:00.000Z","modified":"2026-01-01T00:00:00.000Z"},"versions":{"2.0.0":{}}} {"x":1}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      abbreviated) printf '{"name":"fresh","dist-tags":{"latest":"2.0.0"},"modified":"2026-01-01T00:00:00.000Z","versions":{"2.0.0":{}}}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      name-only) printf '{"name":"fresh"}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      unlisted) printf '{"name":"fresh","time":{"1.0.0":"2000-01-01T00:00:00.000Z","modified":"2026-01-01T00:00:00.000Z"},"versions":{"1.0.0":{}}}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      no-modified) printf '{"name":"fresh","time":{},"versions":{"2.0.0":{}}}\n' > "${CASE_DIR}/reg/packuments/fresh.json" ;;
      not-found) ;;
      unreachable) cooldown_registry_stop; export LANE_RELEASES_BASE=http://127.0.0.1:1 ;;
    esac
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
    cooldown_registry_stop
    assert_status 102 "$FUNCNAME: ${cause}" || return
    assert_lane_final_line update "$FUNCNAME: ${cause}" || return
    assert_err_contains_fragment '1 publish time(s) could not be read, so the cooldown cannot be judged for them (first: fresh@2.0.0: '"${want}" "$FUNCNAME: ${cause}" || return
    assert_log_not_contains_fragment $'REAL\tnpm\tci\t--ignore-scripts' "$FUNCNAME: ${cause}" || return
    # a lockfile judged on missing evidence is refused, so nothing was recorded as a baseline
    [[ -z "$(ls -A "${HOME_DIR}/.local/share/safe/project-lane/state/project-baseline" 2>/dev/null)" ]] || { fail "$FUNCNAME: ${cause}: a lockfile was recorded"; return; }
  done <<'CAUSES'
status|the registry answered HTTP 503
redirect|the registry answered HTTP 301
wrong-package|the registry's answer is for another package
garbled|the registry's answer is not one complete full packument
truncated|the registry's answer is not one complete full packument
trailing|the registry's answer is not one complete full packument
abbreviated|the registry's answer lists this version without a time and carries no last-modified time
name-only|the registry's answer is not one complete full packument
unlisted|the registry's answer does not list this version
no-modified|the registry's answer lists this version without a time and carries no last-modified time
not-found|the registry answered HTTP 404
unreachable|the registry could not be reached
CAUSES
  # the missing readings are counted
  lane_prepare "lane-cooldown-fail-count" kept@1.0.0
  LANE_RELEASES_BASE=http://127.0.0.1:1 NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0 other@1.0.0)" lane_run 'npm update'
  assert_status 102 "$FUNCNAME: count" || return
  assert_err_contains_fragment '2 publish time(s) could not be read' "$FUNCNAME: count" || return
  pass "$FUNCNAME"
}

# A reading is cached per exact version, in the lane's own store, and only what safe itself read is trusted: an entry that
# fails the checks of the recorded lockfiles (a directory that is not private, a link, a file of another mode) or that was
# made for another source is ignored and the registry is asked again; a good one is reused.
case_project_lane_cooldown_cache_holds_only_what_safe_read() {
  skip_lockdiff_case "$FUNCNAME" || return
  local store="" source how n
  plant() { # <source> [mode]: an entry that says fresh@2.0.0 is two years old, in the store's layout
    local src="$1" d="${store}/$(printf '%s' "$1" | sha256sum | cut -d' ' -f1)" f
    mkdir -p "${d}" "${store}" 2>/dev/null
    chmod 700 "${store}" "${d}"
    f="${d}/$(printf 'fresh\0002.0.0' | sha256sum | cut -d' ' -f1)"
    printf '{"schema_version":1,"source":"%s","name":"fresh","version":"2.0.0","published":"2020-01-01T00:00:00Z"}\n' "${src}" > "${f}"
    chmod "${2:-600}" "${f}"
    printf '%s' "${f}"
  }
  for how in private-group-writable-store link wrong-mode other-source canonical-for-a-mirror; do
    lane_prepare "lane-cooldown-cache-${how}" kept@1.0.0
    store="${HOME_DIR}/.local/share/safe/project-lane/state/publish-times"
    cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=10" "kept@1.0.0=2400"
    source="${LANE_RELEASES_BASE}"
    local f
    case "${how}" in
      private-group-writable-store) f="$(plant "${source}")"; chmod 770 "$(dirname "${f}")" ;;
      link) f="$(plant "${source}")"; cp "${f}" "${CASE_DIR}/elsewhere"; chmod 600 "${CASE_DIR}/elsewhere"; rm -f "${f}"; ln -s "${CASE_DIR}/elsewhere" "${f}" ;;
      wrong-mode) f="$(plant "${source}" 644)" ;;
      other-source) plant "http://mirror.example" >/dev/null ;;
      canonical-for-a-mirror) plant "https://registry.npmjs.org" >/dev/null ;;
    esac
    : > "${CASE_DIR}/reg/log"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
    n="$(grep -c '^GET /fresh' "${CASE_DIR}/reg/log")"
    cooldown_registry_stop
    assert_status 100 "$FUNCNAME: ${how}: the planted entry cleared the wait" || return
    assert_err_contains_fragment 'fresh@2.0.0 was published ' "$FUNCNAME: ${how}" || return
    [[ "${n}" == 1 ]] || { fail "$FUNCNAME: ${how}: the registry was asked ${n} times, not once (the entry was trusted)"; return; }
  done
  # the same entry in a store that passes every check is a reading safe made: it is reused, the registry is not asked
  lane_prepare "lane-cooldown-cache-reused" kept@1.0.0
  store="${HOME_DIR}/.local/share/safe/project-lane/state/publish-times"
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=10" "kept@1.0.0=2400"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
  assert_status 100 "$FUNCNAME: first reading" || return
  n="$(grep -c '^GET /fresh' "${CASE_DIR}/reg/log")"
  : > "${CASE_DIR}/reg/log"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
  cooldown_registry_stop
  [[ "${n}" == 1 && "$(grep -c '^GET /fresh' "${CASE_DIR}/reg/log")" == 0 ]] || { fail "$FUNCNAME: the reading safe made was not reused"; return; }
  [[ "$(stat -c %a "${store}")" == 700 ]] || { fail "$FUNCNAME: the store is not private"; return; }
  pass "$FUNCNAME"
}

# Today's security-fix exemption, with its enforce setting, for the version the caller named; a young fix nobody named is
# not selected.
# The security-fix exemption is differential: the named exact version must REPLACE a version of the same package in the
# baseline and thereby remove an advisory the baseline carries for it, as the lane's own advisory reading shows.
# The security-fix waiver is differential and local: the named exact version must REPLACE, at the same place in the graph, a
# baseline version of the same package that an advisory affects, and the advisory must be gone from the result.
# (A withdrawn advisory is removed by the reader itself: tests/audit/scanner_batch.sh, with a detail that says so.)
case_project_lane_cooldown_security_fix_waiver_is_differential() {
  skip_lockdiff_case "$FUNCNAME" || return
  local hit='[{"id":"GHSA-fix-0001","severity":"high","malware":false}]' hits nested target
  hits="{\"fresh@1.0.0\":${hit}}"
  # an affected upgrade: waived, and the report names what it removes
  lane_prepare "lane-cooldown-fix-affected" kept@1.0.0 fresh@1.0.0
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=10" "kept@1.0.0=2400" "fresh@1.0.0=2400"
  SAFE_AUDIT_EVIDENCE_HITS="${hits}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 0 "$FUNCNAME: affected upgrade" || return
  assert_err_contains_fragment 'waived as the security fix it names: fresh@2.0.0 (fixes GHSA-fix-0001)' "$FUNCNAME: affected" || return
  # a downgrade that removes the advisory is waived too (any different version at the same place)
  lane_prepare "lane-cooldown-fix-downgrade" kept@1.0.0 fresh@3.0.0
  SAFE_AUDIT_EVIDENCE_HITS="{\"fresh@3.0.0\":${hit}}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 0 "$FUNCNAME: downgrade" || return
  # the reviewer's shape: the direct fresh@1.0.0 is UNAFFECTED and is replaced by the named one; an AFFECTED nested
  # fresh@0.9.0 disappears with its parent. The advisory is fixed, but the named version removed no exposure: it waits.
  lane_prepare "lane-cooldown-fix-nested" kept@1.0.0 fresh@1.0.0
  nested="$(lane_lock kept@1.0.0 fresh@1.0.0 | jq -c '.packages["node_modules/kept/node_modules/fresh"] = (.packages["node_modules/fresh"] + {version: "0.9.0", resolved: "https://registry.npmjs.org/fresh/-/fresh-0.9.0.tgz"})')"
  printf '%s\n' "${nested}" > "${WORK_DIR}/package-lock.json"
  lane_commit
  SAFE_AUDIT_EVIDENCE_HITS="{\"fresh@0.9.0\":${hit}}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 100 "$FUNCNAME: nested affected disappears" || return
  assert_err_not_contains_fragment 'waived as' "$FUNCNAME: nested" || return
  assert_err_contains_fragment '1 fixed' "$FUNCNAME: nested (the advisory IS fixed, the version just removed no exposure)" || return
  # a true affected replacement beside another version that stays: waived
  lane_prepare "lane-cooldown-fix-beside" kept@1.0.0 fresh@1.0.0
  nested="$(lane_lock kept@1.0.0 fresh@1.0.0 | jq -c '.packages["node_modules/kept/node_modules/fresh"] = (.packages["node_modules/fresh"] + {version: "0.8.0", resolved: "https://registry.npmjs.org/fresh/-/fresh-0.8.0.tgz"})')"
  printf '%s\n' "${nested}" > "${WORK_DIR}/package-lock.json"
  lane_commit
  target="$(lane_lock kept@1.0.0 fresh@2.0.0 | jq -c '.packages["node_modules/kept/node_modules/fresh"] = (.packages["node_modules/fresh"] + {version: "0.8.0", resolved: "https://registry.npmjs.org/fresh/-/fresh-0.8.0.tgz"})')"
  cooldown_registry_start "${CASE_DIR}" "fresh@2.0.0=10" "fresh@0.8.0=2400" "kept@1.0.0=2400"
  SAFE_AUDIT_EVIDENCE_HITS="${hits}" NPM_LOCK_MUTATION_JSON="${target}" lane_run 'npm install fresh@2.0.0'
  assert_status 0 "$FUNCNAME: affected replacement beside another version" || return
  assert_err_contains_fragment 'waived as the security fix it names: fresh@2.0.0 (fixes GHSA-fix-0001)' "$FUNCNAME: beside" || return
  # enforce: the wait stays and says why
  lane_prepare "lane-cooldown-fix-enforce" kept@1.0.0 fresh@1.0.0
  cooldown_config 3 enforce
  SAFE_AUDIT_EVIDENCE_HITS="${hits}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 100 "$FUNCNAME: enforce" || return
  assert_err_contains_fragment 'it fixes GHSA-fix-0001, but install.cooldown_security_fix is enforce' "$FUNCNAME: enforce" || return
  # an unaffected upgrade (the baseline's version carries no advisory): nothing is removed, the version waits
  lane_prepare "lane-cooldown-fix-unaffected" kept@1.0.0 fresh@1.0.0
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 100 "$FUNCNAME: unaffected upgrade" || return
  assert_err_not_contains_fragment 'waived as' "$FUNCNAME: unaffected" || return
  # a fresh add: the project has no version of it, so a fix removes nothing for the project
  lane_prepare "lane-cooldown-fix-fresh-add" kept@1.0.0
  SAFE_AUDIT_EVIDENCE_HITS="${hits}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  assert_status 100 "$FUNCNAME: fresh add" || return
  assert_err_not_contains_fragment 'waived as' "$FUNCNAME: fresh add" || return
  # the same upgrade reached by an update, which names nothing, is a wait: a young fix nobody named is not selected
  lane_prepare "lane-cooldown-fix-unnamed" kept@1.0.0 fresh@1.0.0
  SAFE_AUDIT_EVIDENCE_HITS="${hits}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm update'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME: unnamed" || return
  assert_err_not_contains_fragment 'waived as' "$FUNCNAME: unnamed" || return
  pass "$FUNCNAME"
}

# The cooldown's failures are the lane's: an npm that does not define the exclusion option refuses, a reader that fails or
# a document that lacks its members is breakage, never a pass.
# The cooldown's failures are the lane's: an npm that does not define the exclusion option refuses; a reader that fails, a
# document that is not whole or one the decision cannot read leave the readings MISSING (102), applied after what the
# evidence already establishes: a blocklist hit or a blocking advisory is decided first (104, the block's line).
case_project_lane_cooldown_failures_are_breakage_and_a_known_block_comes_first() {
  skip_lockdiff_case "$FUNCNAME" || return
  local tamper
  lane_prepare "lane-cooldown-capability" kept@1.0.0
  NODE_CAPABILITY_JSON='{"version":"11.12.1","atFloor":true,"missing":["min-release-age-exclude"]}' lane_run 'npm install clean@2.0.0'
  lane_unsupported_case "$FUNCNAME: no exclusion option" install 'an npm without the exclusion option' || return
  assert_err_contains_fragment 'does not define min-release-age-exclude' "$FUNCNAME: no exclusion option" || return
  for tamper in releases-fails releases-garbled releases-foreign-member; do
    lane_prepare "lane-cooldown-${tamper}" kept@1.0.0
    SAFE_CORE_TAMPER="${tamper}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    assert_status 102 "$FUNCNAME: ${tamper}" || return
    assert_lane_final_line install "$FUNCNAME: ${tamper}" || return
    assert_err_contains_fragment 'publish time(s) could not be read, so the cooldown cannot be judged for them' "$FUNCNAME: ${tamper}" || return
    # the readings are set aside as missing; npm's frozen install never ran
    assert_log_not_contains_fragment $'REAL\tnpm\tci\t--ignore-scripts' "$FUNCNAME: ${tamper}" || return
    # the same failure with an established block: the block's line and exit, not the reader's
    lane_prepare "lane-cooldown-${tamper}-block" kept@1.0.0
    SAFE_CORE_TAMPER="${tamper}" SAFE_AUDIT_EVIDENCE_BLOCKLIST='[{"name":"clean","reason":"operator blocklist"}]' \
      NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    assert_status 104 "$FUNCNAME: ${tamper} with a blocklist hit" || return
    assert_lane_final_line install "$FUNCNAME: ${tamper} with a blocklist hit" || return
    assert_err_contains_fragment 'blocklist entry on clean@2.0.0' "$FUNCNAME: ${tamper} with a blocklist hit" || return
    lane_prepare "lane-cooldown-${tamper}-advisory" kept@1.0.0
    SAFE_CORE_TAMPER="${tamper}" SAFE_AUDIT_EVIDENCE_HITS="{\"clean@2.0.0\":${LANE_HIT_CRITICAL}}" \
      NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    assert_status 104 "$FUNCNAME: ${tamper} with a blocking advisory" || return
    assert_err_contains_fragment 'blocking advisory' "$FUNCNAME: ${tamper} with a blocking advisory" || return
  done
  lane_prepare "lane-cooldown-no-request" kept@1.0.0
  SAFE_CORE_TAMPER=diff-no-cooldown-request NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  [[ "${STATUS}" -ne 0 ]] || { fail "$FUNCNAME: a difference without its cooldown request was accepted"; return; }
  assert_lane_final_line install "$FUNCNAME: no request" || return
  lane_prepare "lane-cooldown-no-section" kept@1.0.0
  SAFE_CORE_TAMPER=decide-no-cooldown NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  [[ "${STATUS}" -ne 0 ]] || { fail "$FUNCNAME: a report without its cooldown was accepted"; return; }
  assert_lane_final_line install "$FUNCNAME: no section" || return
  pass "$FUNCNAME"
}

# install.cooldown_days is validated as a decimal string before any arithmetic: a value the lane cannot honour refuses with a
# configuration error that names the key, nothing is capped or wrapped; the others read as today's auditor reads them.
case_project_lane_cooldown_days_are_validated_before_arithmetic() {
  skip_lockdiff_case "$FUNCNAME" || return
  local value want
  # JSON value|the window on the command line (honoured), "refuse" when the lane cannot honour it
  while IFS='|' read -r value want; do
    lane_prepare "lane-cooldown-days-${RANDOM}" kept@1.0.0
    printf '{"install":{"project_lane":true,"cooldown_days":%s}}\n' "${value}" > "${HOME_DIR}/.config/safe/run/config.json"
    : > "${LOG_FILE}"
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm update'
    if [[ "${want}" == refuse ]]; then
      assert_status 100 "$FUNCNAME: ${value}" || return
      assert_lane_final_line update "$FUNCNAME: ${value}" || return
      assert_err_contains_fragment 'the configuration key install.cooldown_days is ' "$FUNCNAME: ${value}" || return
      assert_err_contains_fragment 'which the lane cannot honour (a whole number of days from 0 to 36500)' "$FUNCNAME: ${value}" || return
      assert_log_not_contains_fragment $'REAL\tnpm\t' "$FUNCNAME: ${value}: npm ran" || return
    else
      assert_status 0 "$FUNCNAME: ${value}" || return
      grep -qP "^PROJECTION\tnpm\t.*\t--min-release-age=${want}\t" "${LOG_FILE}" || { fail "$FUNCNAME: ${value}: the window is not ${want}"; return; }
    fi
  done <<'VALUES'
4000|4000
36500|36500
36501|refuse
99999999999999999999|refuse
12345678901234567890|refuse
"99999"|refuse
0|0
"007"|7
"0000000000000000000000000000000000000000042"|42
4e3|4000
36500.0|36500
4E3|4000
4e4|refuse
1e50|refuse
36500.5|3
1e-1|3
-3|3
3.5|3
"soon"|3
true|3
null|3
VALUES
  pass "$FUNCNAME"
}

# The registry's fractional seconds are kept through the reading and the decision, and the retry time printed is rounded UP to
# the second: never earlier than eligibility.
case_project_lane_cooldown_keeps_fractional_seconds_and_rounds_the_retry_time_up() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-cooldown-precision" kept@1.0.0
  cooldown_registry_start "${CASE_DIR}" "kept@1.0.0=2400"
  local whole want
  whole="$(date -u -d '10 hours ago' +%Y-%m-%dT%H:%M:%S)"
  printf '{"name":"fresh","time":{"2.0.0":"%s.359Z","modified":"%s.500Z"},"versions":{"2.0.0":{}}}\n' "${whole}" "${whole}" > "${CASE_DIR}/reg/packuments/fresh.json"
  want="$(date -u -d "${whole}Z + 3 days + 1 second" +%Y-%m-%dT%H:%M:%SZ)"
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 fresh@2.0.0)" lane_run 'npm install fresh@2.0.0'
  cooldown_registry_stop
  assert_status 100 "$FUNCNAME" || return
  assert_err_contains_fragment "fresh@2.0.0 was published ${whole}.359Z and is inside the 3-day cooldown; it becomes installable on ${want}" "$FUNCNAME" || return
  pass "$FUNCNAME"
}

# A block established by the evidence (a blocklist hit, a blocking advisory) is decided BEFORE any publish time is read: the
# command ends 104 with the block's line, and the registry is never asked (no network wait under the project lock).
case_project_lane_cooldown_a_known_block_is_decided_before_any_publish_time_is_read() {
  skip_lockdiff_case "$FUNCNAME" || return
  local what
  for what in blocklist advisory; do
    lane_prepare "lane-cooldown-block-first-${what}" kept@1.0.0
    cooldown_registry_start "${CASE_DIR}" "clean@2.0.0=10" "kept@1.0.0=2400"
    : > "${LOG_FILE}"
    if [[ "${what}" == blocklist ]]; then
      SAFE_AUDIT_EVIDENCE_BLOCKLIST='[{"name":"clean","reason":"operator blocklist"}]' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    else
      SAFE_AUDIT_EVIDENCE_HITS="{\"clean@2.0.0\":${LANE_HIT_CRITICAL}}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    fi
    assert_status 104 "$FUNCNAME: ${what}" || return
    assert_lane_final_line install "$FUNCNAME: ${what}" || return
    [[ ! -s "${CASE_DIR}/reg/log" ]] || { fail "$FUNCNAME: ${what}: the registry was asked ($(head -n1 "${CASE_DIR}/reg/log"))"; return; }
    assert_log_not_contains_fragment 'RELEASES_REQUEST' "$FUNCNAME: ${what}: the reader was started" || return
    cooldown_registry_stop
  done
  pass "$FUNCNAME"
}

# The lane's advisory reader is the one beside safe's dispatcher, never one the caller names: SAFE_AUDIT_BIN, SAFE_AUDIT_PATH
# or a safe-audit first on PATH do not change the lane's evidence.
case_project_lane_cooldown_reads_its_advisories_from_the_reader_beside_the_dispatcher() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-reader-beside" kept@1.0.0
  mkdir -p "${CASE_DIR}/fake-bin"
  printf '#!/bin/sh\nexit 0\n' > "${CASE_DIR}/fake-bin/safe-audit"
  chmod +x "${CASE_DIR}/fake-bin/safe-audit"
  : > "${LOG_FILE}"
  # the caller names a reader that reports nothing; the evidence is still the one beside the dispatcher (it knows the block)
  SAFE_AUDIT_BIN=/bin/true SAFE_AUDIT_PATH="${CASE_DIR}/fake-bin/safe-audit" SAFE_TEST_PATH_MID="${CASE_DIR}/fake-bin" \
    SAFE_AUDIT_EVIDENCE_BLOCKLIST='[{"name":"clean","reason":"operator blocklist"}]' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  unset SAFE_TEST_PATH_MID
  assert_status 104 "$FUNCNAME" || return
  assert_err_contains_fragment 'blocklist entry on clean@2.0.0' "$FUNCNAME" || return
  assert_log_contains $'EVIDENCE_INPUT\t["clean@2.0.0","kept@1.0.0"]' "$FUNCNAME: the reader beside the dispatcher was not the one asked" || return
  # a reader that is not installed beside the dispatcher is breakage, whatever the caller names
  lane_prepare "lane-reader-missing" kept@1.0.0
  rm -f "${BIN_DIR}/safe-audit"
  SAFE_AUDIT_BIN=/bin/true SAFE_AUDIT_PATH=/bin/true NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 102 "$FUNCNAME: no reader beside the dispatcher" || return
  assert_err_contains_fragment 'the advisory reader is unavailable' "$FUNCNAME: no reader" || return
  pass "$FUNCNAME"
}

# ---- Socket on a named root (ticket 1636) ---------------------------------------------------------------------------
#
# The lane asks the reader beside the dispatcher for Socket's facts on the named roots, in its evidence-only mode (asks
# nothing, decides nothing, records nothing), and decides them in safe-core. Every outcome keeps today's gate's exit
# and final-line wording.

# Files the install gates would write for an install (install-known, consents, receipts, grants): everything under the
# test home but the lane's own directory, which holds its baseline and reports.
lane_state_listing() {
  find "${HOME_DIR}/.config/safe" "${HOME_DIR}/.local/share/safe" "${HOME_DIR}/.cache/safe" -type f -not -path '*/project-lane/*' -not -path '*/.config/safe/run/config.json' 2>/dev/null | sort | xargs -r sha256sum
}

case_project_lane_socket_every_outcome_keeps_todays_exit_and_wording() {
  skip_lockdiff_case "$FUNCNAME" || return
  local row outcome status want_word before
  for row in \
      'adverse|100|safe audit verdict WARN (Socket: WARN (score=40))' \
      'rate_limited|102|Socket is rate-limited, so its score is missing' \
      'consent_required|102|fresh release inside the Socket window' \
      'pending|102|the Socket score for the fresh release is still pending, so this install is not all-green' \
      'unavailable|102|audit infrastructure is unavailable (not a package finding)' \
      'blocked|104|Socket BLOCK on clean@2.0.0' \
      'clear|0|'; do
    outcome="${row%%|*}"; status="${row#*|}"; want_word="${status#*|}"; status="${status%%|*}"
    lane_prepare "lane-socket-${outcome}" kept@1.0.0
    before="$(lane_digests)"
    SAFE_AUDIT_SOCKET_OUTCOMES="{\"clean@2.0.0\":\"${outcome}\"}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
    assert_status "${status}" "$FUNCNAME: ${outcome}" || return
    assert_err_contains_fragment 'safe: project lane: socket: 1 named root(s) scored (clean@2.0.0: '"${outcome}" "$FUNCNAME: ${outcome}: the report line" || return
    if [[ "${status}" != 0 ]]; then
      assert_lane_final_line install "$FUNCNAME: ${outcome}" || return
      [[ "$(tail -n 1 "${ERR_FILE}")" == *"${want_word}"* ]] || { fail "$FUNCNAME: ${outcome}: the final line does not say: ${want_word}"; return; }
      [[ "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: ${outcome}: the project changed"; return; }
      assert_log_not_contains_fragment $'REAL\tnpm\tci\t--ignore-scripts' "$FUNCNAME: ${outcome}" || return
    fi
    # the reader is asked once for the roots (one call, whatever the outcome)
    [[ "$(grep -c $'^SOCKET_REQUEST\t{"roots":\\["clean@2.0.0"\\]' "${LOG_FILE}")" == 1 ]] || { fail "$FUNCNAME: ${outcome}: the roots were not asked exactly once"; return; }
    assert_no_per_root_audit "$FUNCNAME: ${outcome}" || return
  done
  # an adverse finding outranks a rate limit among the roots: policy (100) first
  lane_prepare "lane-socket-order" kept@1.0.0
  SAFE_AUDIT_SOCKET_OUTCOMES='{"clean@2.0.0":"rate_limited","other@1.0.0":"adverse"}' NPM_PROJECTION_MANIFEST_JSON="${LANE_TWO_DEPS_MANIFEST}" \
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0 other@1.0.0)" lane_run 'npm install clean@2.0.0 other@1.0.0'
  assert_status 100 "$FUNCNAME: adverse outranks the operator's states" || return
  assert_err_contains_fragment 'other@1.0.0: safe audit verdict WARN' "$FUNCNAME: the adverse root is named" || return
  pass "$FUNCNAME"
}

# What is scored: the named roots only, by ONE reader call whatever their number; the rest of the target graph is asked of the
# cache alone (a blocking result already cached is malice), with no call.
case_project_lane_socket_scores_the_roots_only_with_one_call() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-socket-one-call" kept@1.0.0
  NPM_PROJECTION_MANIFEST_JSON="${LANE_TWO_DEPS_MANIFEST}" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0 other@1.0.0)" lane_run 'npm install clean@2.0.0 other@1.0.0'
  assert_status 0 "$FUNCNAME" || return
  [[ "$(grep -c '^SOCKET_REQUEST' "${LOG_FILE}")" == 2 ]] || { fail "$FUNCNAME: more than the cache reading and one roots call"; return; }
  assert_log_contains $'SOCKET_REQUEST\t{"roots":[],"cached":["clean@2.0.0","kept@1.0.0","other@1.0.0"]}' "$FUNCNAME: the cache is read for the whole graph" || return
  assert_log_contains $'SOCKET_REQUEST\t{"roots":["clean@2.0.0","other@1.0.0"],"cached":[]}' "$FUNCNAME: the roots are the named versions only, in one call" || return
  assert_err_contains_fragment 'socket: 2 named root(s) scored (clean@2.0.0: clear, other@1.0.0: clear)' "$FUNCNAME: report" || return
  # nothing named (a bare install) scores no root and makes no roots call
  lane_prepare "lane-socket-no-roots" kept@1.0.0
  NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0)" lane_run 'npm install'
  assert_status 0 "$FUNCNAME: no root" || return
  ! grep -qP '^SOCKET_REQUEST\t\{"roots":\["' "${LOG_FILE}" || { fail "$FUNCNAME: a roots call was made with nothing named"; return; }
  assert_err_contains_fragment 'socket: 0 named root(s) scored; no other artifact is scored' "$FUNCNAME: no root report" || return
  pass "$FUNCNAME"
}

# Malice from Socket over the whole target graph, from the cache alone: a blocking result already cached for a dependency
# nobody named ends the command (104) before any call is made for the roots.
case_project_lane_socket_a_cached_block_anywhere_in_the_graph_is_malice() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-socket-cached-block" kept@1.0.0
  local before
  before="$(lane_digests)"
  SAFE_AUDIT_SOCKET_CACHED_BLOCKS='["kept@1.0.0"]' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 104 "$FUNCNAME" || return
  assert_lane_final_line install "$FUNCNAME" || return
  [[ "$(tail -n 1 "${ERR_FILE}")" == *'Socket BLOCK on kept@1.0.0'* ]] || { fail "$FUNCNAME: the final line does not name the cached block"; return; }
  # an established block ends the command before any call is made for the named roots
  ! grep -qP '^SOCKET_REQUEST\t\{"roots":\["' "${LOG_FILE}" || { fail "$FUNCNAME: a call was made for the roots after a block"; return; }
  [[ "$(lane_digests)" == "${before}" ]] || { fail "$FUNCNAME: the project changed"; return; }
  # a block cached for something the target does not carry is not this command's
  lane_prepare "lane-socket-cached-elsewhere" kept@1.0.0
  SAFE_AUDIT_SOCKET_CACHED_BLOCKS='["elsewhere@9.9.9"]' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 0 "$FUNCNAME: a block of something outside the target" || return
  # a cache that cannot be read is missing evidence (102), never a clean cache; a known block still comes first
  lane_prepare "lane-socket-cache-gap" kept@1.0.0
  SAFE_AUDIT_SOCKET_CACHE_GAP="the Socket cache could not be read" NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 102 "$FUNCNAME: cache gap" || return
  assert_err_contains_fragment 'the Socket cache could not be read' "$FUNCNAME: cache gap" || return
  lane_prepare "lane-socket-cache-reader-fails" kept@1.0.0
  SAFE_AUDIT_SOCKET_CACHE_STATUS=3 NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 102 "$FUNCNAME: cache reader fails" || return
  assert_err_contains_fragment 'the Socket cache could not be read' "$FUNCNAME: cache reader fails" || return
  lane_prepare "lane-socket-gap-then-block" kept@1.0.0
  SAFE_AUDIT_SOCKET_CACHE_GAP="the Socket cache could not be read" SAFE_AUDIT_EVIDENCE_BLOCKLIST='[{"name":"clean","reason":"operator blocklist"}]' \
    NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  assert_status 104 "$FUNCNAME: a known block outranks the gap" || return
  pass "$FUNCNAME"
}

# A roots reader that fails, or whose document is not whole, is breakage on each root (102), never a clear result.
case_project_lane_socket_a_reader_that_fails_is_breakage_never_clear() {
  skip_lockdiff_case "$FUNCNAME" || return
  local label
  for label in status raw empty; do
    lane_prepare "lane-socket-reader-${label}" kept@1.0.0
    case "${label}" in
      status) SAFE_AUDIT_SOCKET_STATUS=3 NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0' ;;
      raw) SAFE_AUDIT_SOCKET_RAW='{"schema_version":1,"roots":"x"}' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0' ;;
      empty) SAFE_AUDIT_SOCKET_RAW='' SAFE_AUDIT_SOCKET_STATUS=0 NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0' ;;
    esac
    assert_status 102 "$FUNCNAME: ${label}" || return
    assert_lane_final_line install "$FUNCNAME: ${label}" || return
    assert_err_contains_fragment 'audit infrastructure is unavailable (not a package finding)' "$FUNCNAME: ${label}" || return
  done
  pass "$FUNCNAME"
}

# The reader is the one beside safe's dispatcher, whatever the caller names.
case_project_lane_socket_is_read_by_the_reader_beside_the_dispatcher() {
  skip_lockdiff_case "$FUNCNAME" || return
  lane_prepare "lane-socket-reader-beside" kept@1.0.0
  mkdir -p "${CASE_DIR}/fake-bin"
  printf '#!/bin/sh\ncat >/dev/null\nprintf %%s '"'"'{"schema_version":1,"roots":[],"cached_blocks":[],"cache_gap":"","untied":[]}'"'"'\n' > "${CASE_DIR}/fake-bin/safe-audit"
  chmod +x "${CASE_DIR}/fake-bin/safe-audit"
  SAFE_AUDIT_BIN="${CASE_DIR}/fake-bin/safe-audit" SAFE_AUDIT_PATH="${CASE_DIR}/fake-bin/safe-audit" SAFE_TEST_PATH_MID="${CASE_DIR}/fake-bin" \
    SAFE_AUDIT_SOCKET_OUTCOMES='{"clean@2.0.0":"adverse"}' NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0'
  unset SAFE_TEST_PATH_MID
  assert_status 100 "$FUNCNAME" || return
  assert_err_contains_fragment 'clean@2.0.0: safe audit verdict WARN' "$FUNCNAME: the finding of the reader beside the dispatcher" || return
  pass "$FUNCNAME"
}

# Nothing is recorded when the command does not complete: a named root that passes Socket, then a closure refusal or a
# failed materialisation, leaves no install record (no install-known entry, consent, receipt, grant or export), and no
# per-root audit ran that could have written one.
case_project_lane_socket_a_passing_root_records_nothing_when_the_command_does_not_complete() {
  skip_lockdiff_case "$FUNCNAME" || return
  local label before
  for label in closure-refusal failed-materialisation; do
    lane_prepare "lane-socket-records-${label}" kept@1.0.0
    before="$(lane_state_listing)"
    case "${label}" in
      closure-refusal)
        NPM_PROJECTION_MANIFEST_JSON="${LANE_TWO_DEPS_MANIFEST}" SAFE_AUDIT_EVIDENCE_HITS="{\"dirty@3.0.0\":${LANE_HIT_CRITICAL}}" \
          NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0 dirty@3.0.0)" lane_run 'npm install clean@2.0.0' ;;
      failed-materialisation)
        NPM_CI_STATUS=7 NPM_LOCK_MUTATION_JSON="$(lane_lock kept@1.0.0 clean@2.0.0)" lane_run 'npm install clean@2.0.0' ;;
    esac
    case "${label}" in closure-refusal) assert_status 104 "$FUNCNAME: ${label}" || return ;; *) assert_status 7 "$FUNCNAME: ${label}" || return ;; esac
    # the named root PASSED Socket (the reader was asked for it, and it came back clear) or was never asked (a block first)
    [[ "${label}" == closure-refusal ]] || assert_err_contains_fragment 'socket: 1 named root(s) scored (clean@2.0.0: clear)' "$FUNCNAME: ${label}: the root passed" || return
    [[ "$(lane_state_listing)" == "${before}" ]] || { fail "$FUNCNAME: ${label}: something was recorded: $(diff <(printf '%s\n' "${before}") <(lane_state_listing))"; return; }
    assert_no_per_root_audit "$FUNCNAME: ${label}" || return
    assert_log_not_contains_fragment $'AUDIT\tpackage-audit\tclean' "$FUNCNAME: ${label}" || return
  done
  pass "$FUNCNAME"
}

# Already true, shown: a young version the caller NAMES that fixes a baseline advisory installs under exempt and waits
